SET REFERENTIAL_INTEGRITY FALSE;
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (1, 'Solo Leveling: Ragnarok', 'Chugong, Daul', '/uploads/cover_solo_leveling.jpg', 'NOVEL', 'Action, Fantasy, System', 4.9, 'ONGOING', 1, 2024, 'Korea', 'Web Novel', 'Shadow Monarch, Hunters, Dungeons, Overpowered, System, Male Lead', TRUE, FALSE, 'In the shadows of the dimensional rift, a new crisis emerges. Sung Suho, the son of the Shadow Monarch Sung Jinwoo, has lived a normal life until the seals separating the dimensions began to crack. Now, the gates reopen, and the shadows call upon their new lord.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (1, 1, 1, 'The Son of the Monarch', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Sung Suho woke up to a ringing sound in his ears. It wasn''t the grating buzz of his smartphone alarm, nor was it the ambient hum of morning traffic streaming down the asphalt lanes outside his Gangnam studio apartment. It was a cold, piercing oscillation vibrating directly behind his ocular nerves, sharp as a glass shard cutting through fog.</p>

<p>He groaned, pressing the heels of his palms against his temples. A splitting headache throbbed in time with his pulse. On his cluttered desk, an open textbook on Renaissance art history and empty energy drink cans bore silent witness to the night before. He had an exam in less than two hours.</p>

<p>Then, the world around him froze.</p>

<p>The gentle dust motes dancing in the amber morning light suspended motionless in mid-air. The muffled drone of the city abruptly vanished into absolute silence. Before his eyes, translucent azure glyphs materialized, etching glowing lines into the air with sharp, mechanical precision.</p>

<p><b>[System Alert: The Seals of the Shadow Realm are breaking.]</b><br>
<b>[Dimensional stability: 12.4% and dropping.]</b><br>
<b>[Player ''Sung Suho'' has satisfied the awakening conditions.]</b><br>
<b>[The authority of the Shadow Monarch resonates with your bloodline.]</b></p>

<p>"What... what is this&mdash; Suho muttered, his throat dry as sandpaper.</p>

<p>He stared at the blue holographic window floating unblinkingly three feet from his face. He blinked once, twice, vigorously rubbed his eyelids, half-expecting the hallucination to dissipate into the morning glare. It didn''t. If anything, the azure light burned brighter, casting sharp indigo reflections across the white wallpaper.</p>

<p>He looked down at his trembling hands. Beneath his skin, intricate violet veins were beginning to flare with an ethereal luminescence. Black mist&mdash;thick and fluid as liquid ink&mdash;seeped from his pores, coiling around his fingers in lazy, mesmerizing spirals.</p>

<p>A flood of forgotten memories surged through his mind. Childhood dreams he had long dismissed as overactive imagination: a towering sovereign clad in armor blacker than the cosmic void, standing atop a mountain of colossal dragon carcasses, wielding twin daggers that drank the light of dying stars. An infinite army of shadow soldiers with burning blue eyes kneeling in unending ranks, roaring their absolute allegiance into the void.</p>

<p>He had never known where his father disappeared to during those prolonged "business trips." He had only remembered his mother, Cha Hae-in, standing quietly by the balcony window, gazing toward the night sky with a patient, knowing smile. Could that mythic warrior standing at the end of the universe have been... his father?</p>

<p>"No, this has to be a lucid nightmare," Suho whispered, swinging his legs off the mattress. But the instant the soles of his bare feet touched the parquet floor, the room shuddered.</p>

<p>Darkness bled from the corners of the room. The shadows clinging beneath his desk and wardrobe twisted unnaturally, boiling like tar over an open flame. Spatial cracks split the air with the crackle of violet lightning. From the center of the dark pool, a tiny, chitinous creature tumbled onto the floorboards, flapping miniature translucent wings.</p>

<p>It scrambled to its feet, dusted its glossy black carapace, and immediately fell flat onto its face in an extravagant kowtow, slamming its forehead repeatedly against the floor with rhythmic clacks.</p>

<p>"KUWAAAAH! Greetings, Young Monarch!" the miniature ant soldier wailed with dramatic fervour, streams of comical blue tears gushing from its compound eyes. "Ten thousand cycles across the boundless dimensional rift, and at long last, the beacon of your soul has ignited! The Shadow Legion weeps with joy!"</p>

<p>Suho froze mid-step, his jaw practically touching the floorboards. "Did... did an oversized beetle just talk to me&mdash;</p>

<p>"A beetle?!" The ant leaped up in indignation, beating its chest with tiny razor-sharp claws. "I am Beru! Former Marshal of the Shadow Army, guardian of the sovereign bloodline! Left behind by the Great Monarch himself to guide your awakening!"</p>

<p>Suho rubbed his temples again, feeling the migraine intensifying tenfold. "Beru. Right. Listen, Mr. Beru, I don''t know what kind of prank this is, but I have an art history midterm exam in seventy minutes. If I fail, I lose my academic scholarship. Can we reschedule this cosmic awakening for the weekend&mdash;</p>

<p>"Art history?!" Beru gasped in sheer horror, his antennae twitching frantically. "Young master! While the Outer Gods gnaw at the dimensional walls of our world, you speak of petty mortal squiggles?! Look out the window, my lord! The rift has already opened!"</p>

<p>Before Suho could retort, the air was ripped apart by a deafening thunderclap that shattered the double-glazed balcony windows into a thousand glittering shards. An atmospheric shockwave slammed into the apartment, knocking books from the shelves and whipping the curtains violently.</p>

<p>Suho rushed to the shattered balcony, shielding his eyes with his forearm.</p>

<p>High above the Gangnam intersection, the sky had torn open. A colossal dimensional gate&mdash;surging with swirling vortexes of cobalt and blood-red energy&mdash;hung suspended like a bleeding wound in the heavens. Hunter emergency sirens howled through the district, their piercing wails echoing off glass skyscrapers.</p>

<p>Down below, hundreds of cars collided with screeching tires. Screaming pedestrians scrambled in utter panic as nightmarish creatures poured from the gate: wolf-like beasts whose hides dripped black ichor, and gargantuan gargoyles with wings of petrified stone.</p>

<p>A piercing chime chimed inside Suho''s skull, sharper and clearer than before.</p>

<p><b>[Emergency Quest: Defend the Realm of the Living]</b><br>
<b>[Objective: Subdue the Vanguard Beasts invading Gangnam.]</b><br>
<b>[Failure to comply will result in district annihilation.]</b><br>
<b>[Monarch Bloodline: Partially Awakened (Level 1).]</b></p>

<p>Suho looked down at the chaos below. A young mother had tripped on the pavement, desperately shielding her crying child as a three-meter-tall iron-fanged wolf lunged forward, jaws dripping corrosive saliva.</p>

<p>In that split second, something deep within Suho''s chest shattered like thin glass. Fear evaporated, replaced by an ancient, terrifying stillness. His heart beat with thunderous authority. The black mist enveloping his arms solidified into razor-sharp shadow gauntlets, and an electric blue spark flared deep inside his pupils.</p>

<p>"Beru," Suho said quietly, his voice dropping into a register that made the little ant soldier shiver with instinctual reverence.</p>

<p>"Y-Yes, my lord?!"</p>

<p>"How fast can I jump down from the fourth floor&mdash;</p>

<p>"With the Monarch''s blood running in your veins? You will not fall, Sire&mdash;you will descend!"</p>

<p>Without another word, Sung Suho kicked off the balcony railing, hurtling straight into the raging storm of the battlefield.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (2, 1, 2, 'The Shadow Ant''s Request', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Wind howled past Suho''s ears as gravity seized his body. Four stories below, the asphalt rushed upward at dizzying speed.</p>

<p>Instinct took over before rational thought could intervene. Suho channeled the dark mana circulating through his veins downward toward the soles of his feet. An explosion of pitch-black shadows erupted upon impact, cratering the sidewalk with a thunderous boom. Spiderweb fractures rippled outward through ten meters of solid concrete, absorbing every ounce of kinetic force.</p>

<p>Suho stood up straight from the dust, entirely uninjured. His sneakers were enveloped in quiet, drifting coils of indigo smoke.</p>

<p>A few paces away, the iron-fanged wolf paused mid-stride. The beast stood as tall as an SUV, its crimson eyes fixed upon the intruder who had fallen from the sky. Thick, foul-smelling drool hissed as it dissolved the tarmac beneath its paws.</p>

<p><b>[Warning: C-Rank Magical Beast &mdash; Iron-Fanged Shadow Hound detected.]</b><br>
<b>[Target displays extreme hostility.]</b></p>

<p>"Young Master! Be cautious!" Beru shrieked, buzzing into position right above Suho''s shoulder like an agitated hummingbird. "Your human vessel has not yet assimilated the Great Monarch''s vast sea of mana! A single blow from that cur could fracture your ribcage!"</p>

<p>"You could have mentioned that before I jumped out the window!" Suho shouted.</p>

<p>The hound lunged. In a blur of violent motion, the beast traversed thirty feet in a fraction of a second, razor-sharp claws raking horizontally toward Suho''s neck.</p>

<p>Suho didn''t freeze. Time seemed to dilate around him. The beast''s supersonic slash slowed until Suho could discern individual drops of moisture spraying from its jagged muzzle. He dipped his shoulders, ducking cleanly underneath the swipe. The displaced air pressure sliced through the brick wall behind him like a butter knife through warm bread.</p>

<p><i>''Faster. I need to be faster.''</i></p>

<p>Clenching his right fist, Suho poured every ounce of dark aura into his knuckles. The shadows compressed, transforming into a dense, spiked knuckle duster that hummed with kinetic malice.</p>

<p><b>[Skill Activated: Shadow Impact (Lv. 1)]</b></p>

<p>Suho drove his fist directly upward into the beast''s exposed sternum.</p>

<p><b>KRAAAASH!</b></p>

<p>The shockwave blasted outward, blowing away broken glass and car debris for thirty yards. The three-ton wolf was launched vertically into the air, its ribcage caving inward with a sickening crunch. It crashed back onto the asphalt with a lifeless thud, motionless.</p>

<p><b>[Target eliminated.]</b><br>
<b>[You have gained 320 Experience Points.]</b><br>
<b>[Level Up! Your Level is now 2.]</b><br>
<b>[Strength +3, Agility +2, Vitality +2, Intelligence +2, Mana +50.]</b></p>

<p>Suho exhaled a ragged breath, looking down at his fist. The shadow gauntlet slowly dissolved into wisps of smoke, leaving his knuckles bare and unbruised. A warm, invigorating energy surged through his muscles, washing away every trace of exhaustion.</p>

<p>"Glorious! Truly magnificent!" Beru cheered, practically sobbing with adoration as he circled Suho''s head. "The divine instinct of the Monarch shines through! Even with his memories sealed, the sovereign''s blood demands absolute dominance!"</p>

<p>Suho turned around toward the mother and child cowering behind an overturned mailbox. The child''s eyes were wide with awe, clinging to his mother''s jacket. "Are you two all right&mdash; Suho asked softly.</p>

<p>"Y-Yes... thank you... are you a hunter from the Association&mdash; the woman stammered, trembling uncontrollably.</p>

<p>"Just get inside the subway station emergency shelter," Suho urged. "The police barricades should hold there."</p>

<p>As the civilians fled to safety, Suho turned his gaze back toward the city center. Across the boulevard, three more blue portals had torn through the sky. Screams echoed from Teheran Boulevard, accompanied by the distinct sound of assault rifle fire from early-response Hunter squads struggling against overwhelming odds.</p>

<p>"Beru," Suho said, his tone resolute.</p>

<p>"Command me, Sire!"</p>

<p>"How many beasts are pouring out of those gates&mdash;</p>

<p>"At least several hundreds, My Lord. Low-tier scouts, but their numbers will rapidly drown the mortal defenders." Beru bowed deeply, hovering in front of Suho''s chest. "Young Master, the time for hesitation has passed. You cannot fight an army alone with two fists. You must unlock what is rightfully yours. Demand the dead to answer your call!"</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (3, 1, 3, 'Gate in the Heart of Seoul', 10, TRUE, CURRENT_TIMESTAMP(), '<p>The heart of Gangnam had transformed into a war zone. Glass and shattered concrete littered the eight-lane highway. Abandoned luxury sedans burned in tangled heaps, sending plumes of oily black smoke churning into the overcast sky.</p>

<p>A squad of C-Rank and B-Rank hunters from the Baekho Guild were holding a defensive perimeter around the subway entrance. Their elemental mages flung fireballs and icicle lances into the horde, but the magical beasts were relentless. Pack after pack of Shadow Black Panthers&mdash;panthers the size of minivans with coats that drank ambient light&mdash;leaped over the barricades with terrifying agility.</p>

<p>"Hold the line! Protect the evacuation corridor!" shouted the squad captain, a towering vanguard wielding a tower shield that was buckling under the relentless claws of three beasts.</p>

<p>A panther flanked him from a blind spot, jaws gaping wide, lunging directly for the captain''s throat.</p>

<p><b>CLANG!</b></p>

<p>A pitch-black dagger deflected the panther''s fangs with sparks of violet lightning. Before the beast could recover, a young man clad in casual college sneakers and jeans drove the blade straight through its skull, pinning it to the asphalt.</p>

<p>The squad captain stared in bewilderment. "Who are you?! Kid, this is an unranked outbreak! You don''t have guild armor!"</p>

<p>"Take your wounded behind the barrier," Suho replied without turning back. His eyes were glowing with an ominous sapphire fire.</p>

<p>From the shadows beneath the fallen panther, a cold whisper tugged at the edges of Suho''s consciousness. A prompt hung in the center of his vision:</p>

<p><b>[Shadow Extraction is available for this target.]</b><br>
<b>[Monarch Authority: Absolute (Level 1).]</b><br>
<b>[Target: Shadow Black Panther (Rank C)]</b><br>
<b>[Command word required to initiate resurrection.]</b></p>

<p>Suho felt the ancient memories within his blood vibrating with electric intensity. It wasn''t something he had been taught; it was a birthright etched into the very helixes of his DNA. He extended his open palm toward the corpse.</p>

<p>The shadows around his boots widened, swallowing the light of the burning cars. The air pressure plunged, sending a chill through the bones of every hunter within fifty yards.</p>

<p>With quiet, chilling authority, Suho spoke the single syllable that once shook the cosmos:</p>

<p><b style="color: #a855f7; font-size: 1.3rem; letter-spacing: 2px;">"ARISE."</b></p>

<p>The world went deathly quiet.</p>

<p>Then, the beast''s shadow began to boil. Jet-black smoke erupted from the fallen corpse, shooting skyward before crashing back down like an obsidian waterfall. From the pool of boiling darkness, a spectral claw emerged, gripping the pavement. Then another.</p>

<p>With an eerie, unearthly roar that shook the very foundation of the surrounding buildings, a phantom beast hauled itself into reality. Its coat was woven from starlight and cosmic void, its eyes burning with loyal violet embers. Intricate dark mist coiled around its paws like ethereal armor.</p>

<p><b>[Shadow Extraction Successful!]</b><br>
<b>[Shadow Beast ''Void Panther 1'' has been added to your Shadow Army.]</b><br>
<b>[Current Shadow Capacity: 1 / 10]</b></p>

<p>The spectral beast turned toward Suho, instantly lowering its massive head until its muzzle touched his sneakers in humble adoration.</p>

<p>The guild hunters collapsed against their shields, their eyes wide with terror and incomprehension.</p>

<p>"H-He... what did he just do&mdash; a healer stammered, dropping her wooden staff. "He brought a dead monster back to life?! Is that necromancy?! No... necromancy smells of rot... this power... it feels divine!"</p>

<p>Suho stroked the spectral beast''s misty brow. The phantom let out a low, rumbling purr that resonated with pure mana.</p>

<p>"Beru," Suho smiled, the rush of power intoxicating and liberating.</p>

<p>"I am here, My Lord!" Beru squeaked proudly from atop a traffic light.</p>

<p>"Tell the rest of the beasts to come out. We have an army to build."</p>'); font-size: 1.2rem;">"ARISE."</b></p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (30, 1, 4, 'Shadow Domain Awakening', 10, TRUE, CURRENT_TIMESTAMP(), '<p>The arrival of the first Shadow Soldier changed the tempo of the battlefield instantly.</p>

<p>Where the hunters of the Baekho Guild had been desperately clinging to a defensive perimeter, Suho advanced. Every step he took left faint footprints of burning violet embers. Beside him, the newly extracted Shadow Panther bounded forward like a living nightmare, its spectral fangs ripping through invading beasts with terrifying efficiency.</p>

<p><b>[Your Shadow Soldier has eliminated a Magic Beast.]</b><br>
<b>[You have gained 280 Experience Points.]</b></p>

<p><b>[Your Shadow Soldier has eliminated a Magic Beast.]</b><br>
<b>[You have gained 310 Experience Points.]</b></p>

<p>System prompts scrolled across Suho''s vision like a cascading waterfall. With each monster that fell, Suho felt his connection to the realm of death deepening. His senses expanded in geometric progression. He could perceive the mana signatures of every living entity within a four-block radius: the ragged heartbeats of trapped civilians on third floors, the faltering mana cores of exhausted guild hunters, and the throbbing nexus of magical energy pulsating deep within the main gate above the Gangnam intersection.</p>

<p>"More," Suho whispered.</p>

<p>He outstretched both arms. The dark aura beneath his feet surged outward like a tidal wave of pitch-black ocean water, blanketing the entirety of the eight-lane boulevard.</p>

<p><b>[Skill Activated: Monarch''s Domain (Lv. 1)]</b><br>
<b>[All friendly Shadow Soldiers within the domain gain +20% Combat Attributes.]</b><br>
<b>[Shadow Extraction range increased by 300%.]</b></p>

<p>Across the entire street, the corpses of eleven fallen shadow panthers and three iron-fanged hounds began to writhe. Black mist coiled from their carcasses like boiling geysers.</p>

<p>"ARISE!"</p>

<p>A chorus of unearthly roars tore through the sky. Eleven spectral panthers and three armored hounds clawed their way out of the asphalt simultaneously. Their spectral violet eyes flared in unison, turning toward Suho and bowing in absolute devotion.</p>

<p><b>[Shadow Extraction Successful: 14 new soldiers added.]</b><br>
<b>[Current Shadow Army: 15 / 20]</b><br>
<b>[Level Up! You have reached Level 5.]</b></p>

<p>The hunters watching from the barricades fell to their knees. The squad captain pinched his own arm until it bruised, unable to comprehend the spectacle unfolding before his eyes.</p>

<p>"A one-man army..." the captain breathed, his voice trembling. "He''s not a hunter... he''s a walking calamity. Who in God''s name is that kid?!"</p>

<p>A news drone, buzzing overhead to broadcast the disaster to nationwide television, zoomed its telephoto lens directly onto Suho''s profile. Across South Korea, millions of citizens glued to breaking news broadcasts watched a young man in everyday clothes commanding a legion of midnight specters that slaughtered the dungeon outbreak in minutes.</p>

<p>Yet Suho wasn''t smiling.</p>

<p>At the center of the dimensional gate above the intersection, the azure portal was turning a sickly, coagulated crimson. The atmospheric pressure plummeted, freezing the rainwater on the street into razor-sharp frost crystals.</p>

<p>"Young Master!" Beru''s voice carried genuine alarm. "The gate''s nature is altering! It is not an ordinary dimensional breach&mdash;it is a Red Gate!"</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (31, 1, 5, 'The Red Dungeon of Gangnam', 15, TRUE, CURRENT_TIMESTAMP(), '<p>A Red Gate.</p>

<p>The term alone sent chills down the spine of every veteran hunter on earth. Unlike ordinary gates that allowed hunters to retreat through the exit portal, a Red Gate instantly severed all dimensional coordinates with Earth. Once sealed, no one could enter from the outside, and no one could leave until either every human inside was devoured, or the Dungeon Boss fell.</p>

<p>A blinding crimson flash enveloped the entire three-block radius of Gangnam. When the light subsided, the skyscrapers, streets, and neon billboards were gone.</p>

<p>In their place stretched an endless, frozen wasteland under a blood-red sky. Howling blizzards swept across jagged mountain ranges of black ice. Temperatures dropped to minus forty degrees Celsius, threatening to freeze human lungs in a matter of seconds.</p>

<p>Trapped inside alongside Suho were twelve hunters from the Baekho squad, shivering uncontrollably as their thermal gear failed against the supernatural cold.</p>

<p>"W-We''re in a Red Gate..." the captain muttered, his lips already turning blue. "God help us... we don''t have rations or arctic survival gear. We''ll freeze to death in three hours!"</p>

<p><b>[System Alert: You have entered the Dimensional Pocket ''Frost Spire''.]</b><br>
<b>[Environmental Hazard: Extreme Hypothermia.]</b><br>
<b>[Monarch''s Body: Temperature resistance active. Cold effects negated.]</b></p>

<p>Suho didn''t feel the cold. The dark mana coursing through his core burned with the ferocity of a miniature sun, keeping his blood warm and vigorous.</p>

<p>From the blizzard ahead, heavy, rhythmic footsteps shook the glaciers. Through the blinding snow appeared silhouettes twice as tall as houses: Frost Goliaths with skin of compacted ice, accompanied by white-furred Dire Wolves whose eyes glowed with ravenous hunger.</p>

<p>Leading them atop a ridge was a towering figure in silver plated armor, wielding an executioner''s broadsword carved from glacial frost. Above its head, glowing crimson letters marked its identity:</p>

<p><b>[Dungeon Boss: Glacial Warlord Kargalgan (A-Rank)]</b></p>

<p>"Insolent insects," the warlord''s voice boomed like an avalanche. "You step into the domain of the Monarch of Frost! Your frozen bones shall pave the road for our return!"</p>

<p>The Baekho squad hunters fell into despair. "An A-Rank boss... we''re dead. There are no S-Rank hunters here to save us!"</p>

<p>Suho walked calmly past the trembling hunters. With a flick of his wrists, two daggers of condensed shadow mana materialized in his grip, hummed with dark violet lightning.</p>

<p>"Beru," Suho said calmly.</p>

<p>"Awaiting your order, my lord!"</p>

<p>"Take ten shadows and circle the flanks. Keep the wolves away from the injured hunters."</p>

<p>"By your sovereign will!" Beru shot into the blizzard like a black bullet.</p>

<p>Suho looked up at the towering Frost Warlord. The fear that once governed his mundane college life was completely extinguished. In its place burned the unyielding, peerless pride of the Shadow Monarch''s successor.</p>

<p>"You wanted an S-Rank hunter&mdash; Suho whispered, vanishing from the snow in an explosion of speed that left a crater of cracked ice. "I am something far worse."</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (2, 'The Apothecary Diaries', 'Natsu Hyuuga', '/uploads/cover_apothecary_diaries.jpg', 'NOVEL', 'Mystery, Historical, Drama', 4.8, 'COMPLETED', 1, 2023, 'Japan', 'Light Novel', 'Court Politics, Herbalist, Smart Female Lead, Poison, Investigation', TRUE, FALSE, 'Maomao, a young woman trained in herbal medicine, is kidnapped and sold as a lowly maid into the Emperor''s rear palace. Using her sharp intellect and deep knowledge of poisons and cures, she unravels palace conspiracies while attempting to keep a low profile.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (4, 2, 1, 'The Poison in the Powder', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The rear palace was a gilded birdcage teeming with two thousand women, smelling of expensive sandalwood, musk perfumes, and simmering rivalries. But beneath the silks and pearl hairpins, a macabre shadow hung over the courtyards: the infant heirs of the imperial consorts were withering away, one by one, struck by a mysterious, incurable wasting disease.</p>

<p>Maomao scrubbed the cobblestone tiles of the laundry corridor with rhythmic, methodical strokes, keeping her bangs low over her eyes. She was seventeen, trained from infancy in the pleasure quarters by an eccentric apothecary who had taught her the anatomy of poisons, herbs, and surgical stitching. She had been kidnapped by bandits while gathering medicinal herbs in the forest and sold into the palace as a common maid.</p>

<p>Her golden rule for surviving her two-year term of indenture was simple: act ignorant, work hard, and avoid court politics at all costs.</p>

<p>However, hearing the palace maids gossip about the "curse of the imperial babies" was grating on her nerves. Consort Lifa''s infant prince had already died, and now Consort Gyokuyou''s tiny princess was vomiting milk, suffering from acute convulsions and skin discoloration.</p>

<p><i>''A demonic curse? Fools,''</i> Maomao thought, wringing out her washcloth with quiet disgust. <i>''There is no such thing as a curse. Only chemical reactions.''</i></p>

<p>She knew precisely what was killing the children. The aristocratic consorts took pride in their immaculate porcelain complexions, achieved by applying copious layers of imported white face powder. And the key ingredient that made that powder so lustrous was lead. When the consorts held their infants, the sweet-tasting toxic dust dusted onto the babies'' skin, was inhaled into their lungs, or swallowed during nursing.</p>

<p>Involving oneself in imperial affairs was a direct path to the executioner''s chopping block. Yet, whenever Maomao caught sight of Consort Gyokuyou cradling her fragile, feverish infant daughter in the Jade Pavilion courtyard, she could not swallow her conscience.</p>

<p>That evening, disguised in the twilight shadows, Maomao crushed dried azalea twigs and ink, penning a brief, clinical warning on a strip of linen: <i>[The white cosmetic powder is sweet, but carries the poison of slow death. Keep it away from infants and nursing mothers.]</i></p>

<p>She tied the message to a blossoming camellia branch and dropped it right outside the Jade Pavilion''s main gate where the Imperial Guards were guaranteed to find it.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (5, 2, 2, 'The Consort''s Banquet', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Maomao''s warning had saved Princess Lingli''s life. While Consort Lifa dismissed the warning and lost her prince, Consort Gyokuyou immediately ordered all lead-based cosmetics thrown into the furnace, and within three days, the little princess''s fever broke.</p>

<p>Unfortunately, it also caught the attention of Jinshi.</p>

<p>Jinshi was the emperor''s high-ranking eunuch administrator, possessing a face of such celestial, breath-taking beauty that both palace women and civil officials blushed into their sleeves whenever he walked by. To Maomao, however, his sweet smile looked like an exquisitely lacquered poisonous centipede.</p>

<p>"So you are the clever little maid who knows about lead toxicity," Jinshi purred, leaning against the lacquered pillar of the Jade Pavilion, observing Maomao with glittering obsidian eyes.</p>

<p>Maomao bowed low until her forehead hovered an inch from the tatami mat. She had deliberately stained her cheeks with juice from buckwheat and camellia to create artificial freckles, hoping to appear thoroughly unremarkable. "This humble servant merely remembered a passage from an ancient foreign herbal manual, My Lord."</p>

<p>"A common maid from the lower district who reads medical treatises in classical characters&mdash; Jinshi chucked softly, stepping closer. "Consort Gyokuyou is deeply grateful to you. She requires someone with sharp wits and a discerning eye to oversee her kitchen. Specifically... a personal food poison taster."</p>

<p>Maomao''s head snapped up. For the first time, the dull, subservient veil vanished from her eyes, replaced by a radiant, uncontainable sparkle of pure ecstasy.</p>

<p>"A poison taster&mdash; she whispered, her lips trembling with joyous anticipation. "You mean... I get to ingest all manners of toxins and antidotes on a daily basis&mdash;</p>

<p>Jinshi blinked, caught entirely off guard by her ecstatic expression. Most people assigned to food tasting wept and drafted their wills. This strange girl looked like a starving child being invited to a royal candy banquet.</p>

<p>"Yes," Jinshi smiled intrigue dancing in his eyes. "Starting with today''s imperial banquet."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (6, 3, 1, 'The End of the Adventure', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The Era Meteor shower falls once every fifty years. For an elf whose lifespan spans millennia, fifty years is merely a blink of an eye, a brief season in an unending afternoon.</p>

<p>Frieren sat on the palace steps of the royal capital alongside her three companions: Himmel the Hero, Eisen the Dwarf warrior, and Heiter the corrupt priest who was already snoring softly with a half-empty flagon of wine resting in his lap. Ten years had passed since they set out to defeat the Demon King, and tonight, the entire empire was celebrating their victorious return.</p>

<p>"It was a good journey, wasn''t it, Frieren&mdash; Himmel asked gently, looking up at the shooting stars trailing across the velvet sky. He was still young, his blue hair catching the light of the festival lanterns, a proud smile gracing his handsome features.</p>

<p>"It was alright. Ten years felt rather short," Frieren replied in her characteristic, emotionless monotone, chewing on a piece of sweet pastry.</p>

<p>Himmel laughed softly. "Only you would call a decade short. Still, these meteors are hard to see from inside the capital walls. In fifty years, when they return, let us travel together to a better viewpoint. I know a quiet hill where the sky opens up completely."</p>

<p>"Very well," Frieren agreed without much thought. To her, fifty years was nothing more than a scheduled appointment to pick up a book.</p>

<p>She packed her luggage the next morning, parted with her companions with a casual wave of her hand, and set off alone across the continent to collect useless spells: magic that turns sour grapes sweet, magic that cleans rust from copper pans, and magic that creates fields of blue flowers.</p>

<p>Fifty years passed like a breeze rustling through autumn leaves.</p>

<p>When Frieren finally returned to the capital, the young hero Himmel was gone. In his place sat a frail, bald old man with a cane and a wrinkled smile that somehow still held the gentle warmth of that starry night. The promised journey to the hill was their last.</p>

<p>At Himmel''s funeral, as his coffin was lowered into the earth beneath showers of white flower petals, the citizens wept openly. Frieren stood quietly at the edge of the crowd, completely dry-eyed.</p>

<p>"Look at that elf," someone whispered bitterly. "She traveled with him for ten years, yet she doesn''t shed a single tear. How heartless."</p>

<p>Then, something cracked deep within Frieren''s chest. Hot, blinding tears spilled down her cheeks, soaking the collar of her white traveling cloak.</p>

<p>"I... I knew human lives were short," Frieren sobbed, clutching her staff as the world blurred. "Why didn''t I try to get to know him better?!"</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (32, 2, 4.0, 'The Courtesan''s Secret Recipe', 10, TRUE, CURRENT_TIMESTAMP(), '<p>A strange illness had fallen over the imperial concubines in the northern wing. Several court ladies developed high fevers accompanied by floral-scented delirium, muttering forgotten love poetry in their sleep.</p><p>Jinshi escorted Maomao through the incense-shrouded corridors. "The court physician claims it is an evil wind from the northern marshes," he remarked, watching her reaction with an amused grin.</p><p>Maomao inspected a half-burned stick of aromatic incense on a carved brass incense burner. She scraped a fingernail of resin and brought it to her nose, sniffing carefully. "Hardly an evil wind. Someone has blended belladonna root with dried oleander pollen into the temple sandalwood. In low doses, it creates vivid dreams; in high doses, heart failure." She turned to Jinshi, her eyebrows raised: "Someone in the palace is attempting to weed out rival consorts before the Emperor''s upcoming festival."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (33, 2, 5.0, 'The Blue Rose at the Outer Pavilion', 15, TRUE, CURRENT_TIMESTAMP(), '<p>An envoy from the western desert kingdoms arrived with an impossible demand: they would seal the silk trade treaty only if the Emperor presented a freshly bloomed bouquet of blue roses at the banquet.</p><p>Roses existed in white, crimson, and pale yellow, but a truly blue rose had never been witnessed under heaven. Panic spread through the imperial gardening department.</p><p>"Can you do it, Maomao&mdash; Jinshi asked, cornering her in her herbal workshop while she was drying dried toads.</p><p>"Nature does not produce blue delphinidin pigments in rose genetics, Lord Jinshi," Maomao replied coldly. "However, if one boils dried indigo leaves in an alkaline solution and waters the white rose bushes through cut xylem stems twenty-four hours before the banquet... capillary action does the trick." Jinshi burst into a delighted laugh, gently patting her head: "I knew I could rely on my odd little poison tester."</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (3, 'Omniscient Reader''s Viewpoint', 'sing N song', '/uploads/cover_omniscient_reader.jpg', 'NOVEL', 'Action, Fantasy, Sci-Fi', 4.9, 'ONGOING', 1, 2021, 'Korea', 'Web Novel', 'Apocalypse, Constellations, Survival, Dokkaebi, Smart Lead', TRUE, FALSE, 'Kim Dokja was an ordinary contractor whose only pastime was following a forgotten web novel with over three thousand chapters. When the final chapter concludes, the author sends a cryptic text—and reality suddenly transforms into the deadly scenarios of that very novel.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (7, 3, 2, 'The Priest''s Lie', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Twenty years after Himmel''s passing, Frieren visited the quiet forest cottage where Heiter had retired. The once-gluttonous priest was now bedridden, his beard white as snow, breathing with shallow, labored rasps.</p>

<p>By his bedside stood a small human girl with purple hair, reading a massive grimoire with serious, unwavering discipline. Her name was Fern, a war orphan Heiter had taken in when her village was razed by northern monsters.</p>

<p>"Frieren... you haven''t changed a bit," Heiter wheezed, offering a frail, familiar smile. "I have a favor to ask of you before I go to meet the Goddess. Will you decipher this ancient grimoire of resurrection, and take Fern as your apprentice&mdash;</p>

<p>Frieren examined the grimoire and shook her head immediately. "Resurrection magic is a myth. The dead do not return. And taking a human apprentice is foolish; humans die too quickly. It is painful."</p>

<p>Heiter did not argue. "Then at least stay until you finish decoding the historical text. It will take five or six years."</p>

<p>Frieren agreed. Over the next five years, she observed young Fern practicing mana manipulation from sunrise to midnight. Fern never complained, never asked for toys or sweet candy, casting mana blasts into the forest boulders until her palms blistered and bled.</p>

<p>"Why do you push yourself so hard&mdash; Frieren asked Fern one afternoon as the girl collapsed against a tree trunk, exhausted.</p>

<p>"Because Heiter-sama took me in when I wanted to die," Fern answered softly, catching her breath. "He told me he could die in peace if he knew I could survive on my own as a recognized mage. I want to show him I can take care of myself before he leaves."</p>

<p>Frieren looked at the girl''s steady, determined eyes, remembering Himmel''s words from decades ago: <i>''Even the smallest memories leave an imprint on this world, Frieren.''</i></p>

<p>When Heiter peacefully closed his eyes that winter, Fern did not break down. She stood tall beside his grave, her staff in hand.</p>

<p>"Let us go, Fern," Frieren said, adjusting her travel satchel. "Our journey to the north begins today."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (8, 3, 2.0, 'Scenario 1: Proof of Value', 0, TRUE, CURRENT_TIMESTAMP(), '<p>A soft blue sphere floated into the train carriage. It cracked open like an egg, revealing a fluffy creature with small horns and glowing crimson eyes—a Dokkaebi.</p><p>"Ah, testing, one two three! Can everyone hear me&mdash; the creature cackled, hovering in mid-air. "From this moment forward, the free trial of your mundane human civilization has officially concluded."</p><p>Blue hologram windows flashed before every passenger''s eyes:</p><p><b>[Main Scenario #1 – Proof of Value]</b><br><b>Category:</b> Main<br><b>Difficulty:</b> F<br><b>Clear Condition:</b> Kill one or more living beings.<br><b>Time Limit:</b> 30 minutes<br><b>Penalty for Failure:</b> Death</p><p>While panic erupted throughout the car, Kim Dokja calmly opened his phone. He knew every rule, every hidden loophole, and every monster of this world.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (9, 4, 1, 'Starting the Paid Service', 0, TRUE, CURRENT_TIMESTAMP(), '<p>There are three ways to survive in a ruined world. Now, I have forgotten a few, but one thing is certain: the fact that you who are reading this will survive.</p>

<p>My name is Kim Dokja. ''Dokja'' can mean an only son, or it can mean a reader. In my case, both definitions fit me like an old, tailored coat. An only child with no special talents, working as a contractor for a sub-tier gaming company, reading web novels on the subway ride home to escape the crushing monotony of reality.</p>

<p>Today was the final day of the longest novel I had ever read: <i>''Three Ways to Survive in a Ruined World''</i>, or simply <i>Ways of Survival</i>. For over ten years and 3,149 chapters, I had been the sole reader who stuck with it to the very end.</p>

<p>I left a comment on the final chapter: <i>[Author-nim, thank you for writing such a wonderful story for ten years. Thanks to your novel, I was able to live through my hardest days.]</i></p>

<p>A few moments later, a notification popped up on my phone. A direct message from the author:</p>

<p><i>[Reader-nim, thanks to you, this story was able to reach its conclusion. As a token of my gratitude, I will send you a small gift. At 7:00 PM tonight, the ''Paid Service'' will commence. Please survive until the very end.]</i></p>

<p>I checked my watch. 6:59 PM. The subway car was rattling along the Dongho Bridge, crossing the Han River. Outside the window, the setting sun painted the water in streaks of crimson gold.</p>

<p>Then, at exactly 7:00 PM, the train screeching to a halt with a violent jolt. The lights inside the carriage flickered and died. A chilling silence enveloped the darkness.</p>

<p>From the pitch-black air, a miniature creature with horns, white fur, and small bat wings materialized, floating with an arrogant grin. A Dokkaebi.</p>

<p>"Ah, can everyone hear me? Testing, one two three!" the creature spoke with a voice that echoed directly inside the passengers'' skulls. "From this moment on, your mundane lives have concluded. Welcome to the Main Scenario."</p>

<p>Blue system screens flared to life before every passenger in the subway car.</p>

<p><b>[Main Scenario #1 &mdash; Proof of Value]</b><br>
<b>[Category: Main]</b><br>
<b>[Difficulty: F]</b><br>
<b>[Clear Condition: Kill one or more living beings.]</b><br>
<b>[Time Limit: 30 minutes.]</b><br>
<b>[Reward: 300 Coins.]</b><br>
<b>[Failure: Death.]</b></p>

<p>I stared at the glowing blue text. The words, the Dokkaebi, the exact scenario conditions&mdash;they were identical to the first chapter of <i>Ways of Survival</i>. The fictional world I had spent a decade reading had just become my reality.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (34, 3, 4.0, 'The Regressor Yoo Joonghyuk', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Crossing the collapsed Dongho Bridge was supposed to be impossible without high-tier defensive skills. Beneath the twisted steel girders, the murky Han River swirled with the gaping jaws of an ichthyosaur.</p><p>Standing atop the highest pillar stood a solitary figure in a black trench coat. Broad shoulders, sharp aristocratic features, and an aura of icy detachment that made the air freeze around him: Yoo Joonghyuk, the regressor protagonist of ''Ways of Survival''.</p><p>"Who are you&mdash; Joonghyuk asked, his dark eyes locking onto Dokja with the cold scrutiny of someone who had lived through hundreds of deaths. "You shouldn''t have survived the carriage scenario with those pathetic stats."</p><p>Dokja smiled, adjusting his cheap necktie. "I''m someone who knows how this world ends, Joonghyuk. And unlike your past regressions, I don''t plan on dying here." Joonghyuk''s grip on his black sword tightened—suspicious, intrigued, and lethal.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (35, 3, 5.0, 'The First Apostle''s Prophecy', 15, TRUE, CURRENT_TIMESTAMP(), '<p>Inside the belly of the giant sea commander ichthyosaur, boiling stomach acid dissolved everything within seconds. But Kim Dokja sat calmly atop a floating mass of digested driftwood, chewing monster meat.</p><p><b>[The Fourth Wall is shaking violently.]</b><br><b>[Constellation ''Prisoner of the Golden Headband'' is pulling his hair in excitement.]</b><br><b>[Constellation ''Secretive Plotter'' is observing your actions.]</b></p><p>Dokja opened his coin shop interface. He poured 5,000 coins directly into his physical constitution and magic power. With the thorn weapon harvested from the ichthyosaur''s palate, he began slicing open the beast''s heart from the inside out.</p><p>"Yoo Joonghyuk thinks he''s the only one who knows the future," Dokja whispered into the darkness as the beast''s death wails shook the river. "Too bad for him. I read all 3,149 chapters."</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (4, 'Frieren: Beyond Journey''s End', 'Kanehito Yamada', '/uploads/cover_frieren.jpg', 'MANGA', 'Fantasy, Adventure, Slice of Life', 4.9, 'ONGOING', 1, 2023, 'Japan', 'Manga', 'Elves, Magic, Journey, Nostalgia, Female Lead', TRUE, FALSE, 'The ten-year quest to fell the Demon King is over. While her human companions celebrate the dawn of an era they will barely outlive, the immortal elf mage Frieren watches time slip away. Spurred by sorrow and longing, she sets forth on a pilgrimage to truly comprehend human hearts.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (10, 4, 2, 'The Protagonist Appears', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Panic erupted in carriage 3807. Office workers screamed, students sobbed, and elderly passengers clawed desperately at the sealed train doors. Nobody believed the Dokkaebi until the timer clicked down to twenty-eight minutes, and an unruly thug attempting to break the windows had his head abruptly detonated like an overripe watermelon.</p>

<p>Blood splattered across the frosted glass. The screams turned into raw, primal terror.</p>

<p>"Now do you believe me, dear bugs&mdash; the Dokkaebi chuckled, floating lazily near the ceiling. "Remember the condition: take a life, or your life will be taken. Twenty-seven minutes remaining!"</p>

<p>I felt cold sweat trickling down my spine. But beneath the fear, my mind was operating with unnatural clarity. Because I was the only person on earth who had read all 3,149 chapters, I knew something no one else did: the scenario did not specify a <i>human</i> life.</p>

<p>I sprinted toward the back of the car where a young boy named Lee Gilyoung was clutching a plastic bug-collecting cage, crying in the corner. Inside the cage crawled grasshoppers.</p>

<p>"Kid," I said gently, crouching down. "Give me the cage. I will save you."</p>

<p>Moments later, I crushed a grasshopper beneath my thumb.</p>

<p><b>[You have cleared Main Scenario #1.]</b><br>
<b>[You have earned 300 Coins.]</b></p>

<p>I handed the remaining insects to the boy and my co-worker Yoo Sangah, allowing them to clear the scenario without becoming murderers. When the thirty-minute timer expired, explosive pops resonated through the car as those who hesitated vanished into mist.</p>

<p>Then, the metal doors connecting our carriage to carriage 3707 buckled inward. Steel screeched as if being torn open by a hydraulic claw.</p>

<p>Through the twisted metal walked a tall man draped in a long black trench coat, carrying a bloodstained sword. His sharp, predatory gaze scanned the blood-soaked car, finally resting on me.</p>

<p>Yoo Joonghyuk. The regressor. The immortal protagonist of <i>Ways of Survival</i> who had lived through countless apocalyptic cycles.</p>

<p>"Who are you&mdash; Yoo Joonghyuk asked, raising his blade toward my throat. "You weren''t in this carriage in my previous life."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (11, 4, 2.0, 'Priest Heiter''s Request', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Years later, Frieren visited Heiter in his secluded countryside home. The once-boisterous holy man was frail, caring for a war orphan named Fern.</p><p>"Frieren," Heiter wheezed with a gentle smile, "I ask of you a favor. Decode this grimoire of immortality... and take Fern as your apprentice."</p><p>"Immortality does not exist, and apprentices are a burden," Frieren replied bluntly. But Heiter only smiled, knowing her heart was kinder than her words. Over the seasons that followed, Frieren taught Fern the art of mana suppression, finding quiet warmth in the rhythm of daily life.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (12, 4, 3.0, 'Journey to Aureole', 15, TRUE, CURRENT_TIMESTAMP(), '<p>With Heiter''s passing, Frieren and young Fern embarked north toward Ende—the realm of souls where the Demon King''s castle once stood.</p><p>"Mistress Frieren," Fern asked as they walked along a field of blue moon flowers, "why do you collect seemingly useless spells like turning sweet grapes sour&mdash;</p><p>Frieren paused, her twintails fluttering in the morning breeze. "Because Himmel once told me that silly spells bring smiles to people''s faces. And that is what a true adventurer does."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (36, 4, 4.0, 'The Village of the Sword', 10, TRUE, CURRENT_TIMESTAMP(), '<p>High in the northern mountains, snow blanketed the sacred sanctuary where the legendary Hero''s Sword stood firmly embedded in an ancient boulder of divine ore.</p><p>Eighty years ago, Himmel had visited this very altar with the party. He had gripped the hilt, pulled with all his might, yet the blade of prophecy did not budge an inch. Himmel was not the destined child of the goddess.</p><p>"Mistress Frieren, wasn''t Master Himmel heartbroken&mdash; Fern asked, adjusting her winter cloak against the freezing gale.</p><p>Frieren looked down at the untouched blade with a nostalgic smile. "Not at all. Himmel just smiled, drew his cheap iron replica, and said: <i>''Who cares about prophecy? A true hero doesn''t need a magical sword to save the world; he just needs the courage to protect those who weep.''</i> And he proved it."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (37, 4, 5.0, 'Aura the Guillotine', 15, TRUE, CURRENT_TIMESTAMP(), '<p>Aura the Guillotine, one of the Seven Sages of Destruction, hovered over the battlefield with her mystical Scales of Obedience. For five hundred years, her scale had weighed the souls of warriors, forcing anyone with less mana than her to become her mindless puppet.</p><p>"Elf mage," Aura sneered, placing her overwhelming demonic mana on the right scale. "You have hidden for eighty years, yet your mana is pathetic. Submit to my will!"</p><p>Frieren stood completely still, her hands resting quietly at her sides. Slowly, the artificial restriction that had suppressed ninety-nine percent of her power for a thousand years dissolved.</p><p>The sky shook. A terrifying, blinding pillar of pure white mana erupted around Frieren, dwarfing Aura''s scale until it shattered completely. Frieren looked down at the trembling demon with empty crimson eyes: "Aura, guillotine yourself."</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (5, 'Cyberpunk: Edgerunners', 'Studio Trigger', '/uploads/cover_cyberpunk.jpg', 'COMIC', 'Sci-Fi, Action, Romance', 4.9, 'COMPLETED', 1, 2022, 'Japan', 'Original', 'Night City, Cyberware, Sandevistan, Mercenary, Dystopia', FALSE, FALSE, 'In a chrome-tinted metropolis governed by mega-corporations and cybernetic excess, young David Martinez loses everything in a stray shootout. Implanting a military-grade Sandevistan neural booster, he dives headfirst into the dangerous mercenary underworld of Night City.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (13, 5, 1.0, 'City of Dreams', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The yellow skyline of Night City loomed over Santo Domingo. David Martinez pulled his cheap school jacket tighter around his shoulders as the metro whirred along the elevated rails.</p><p>His mother worked twelve-hour emergency medical shifts so he could attend the Arasaka Academy. But prestige meant nothing to the corporate kids who mocked his outdated uniform. Then came the shootout on the highway—a drive-by that claimed his mother''s life and left David buried in medical bills he could never repay.</p><p>Sitting in their desolate apartment, David stared at the heavy metallic spinal implant recovered from his mother''s jacket. A prototype Sandevistan. "If I''m going to drown in this city," David thought, contacting a shady ripperdoc, "I''ll do it at the speed of light."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (26, 5, 2.0, 'Like a Boy', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Activating the military chrome sent shockwaves of adrenaline racing through David''s neural network. The world slowed to a crawl: falling rain froze into suspended crystals, and bullets hung motionless in the air.</p><p>That night on the train, he met Lucy—a netrunner with prism-dyed hair and eyes that reflected the moon. When she tried to swipe shards from Arasaka executives, David intervened with supersonic speed, catching her off-guard.</p><p>"You''ve got military chrome in that skinny spine," Lucy whispered, pulling him into her hideout. "Do you have any idea how dangerous that is in Night City&mdash;</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (27, 5, 3.0, 'Smooth Criminal', 20, TRUE, CURRENT_TIMESTAMP(), '<p>Lucy linked their cyberdecks and projected a braindance of the lunar surface. Sitting side by side on virtual moon rock, the suffocating smog of Night City faded away.</p><p>"One day, I''m buying a ticket to the moon," Lucy said quietly, looking up at Earth. "No Arasaka, no badges, no chrome fever. Just quiet."</p><p>David looked at her earnest expression and made a silent vow. "I''ll take you there, Lucy. Whatever it takes, I won''t let Night City burn you."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (38, 5, 4.0, 'All Eyez on Me', 15, TRUE, CURRENT_TIMESTAMP(), '<p>Maine''s crew operated out of the Afterlife''s shadow. Rebecca sat on the hood of their quadra, reloading twin customized shotguns with manic laughter, while Kiwi decrypted high-tier Arasaka navigation shards.</p><p>"Listen up, kid," Maine growled, adjusting his gargantuan chrome cyberarms. "In this line of work, you don''t make mistakes twice. Militech''s convoy is carrying experimental combat chassis down Pacifica Highway. We hit fast, grab the cargo, and vanish before Trauma Team deploys."</p><p>When the escort drones opened fire with heavy Gatling cannons, David clicked his spine. The world paused. Blurring across the tarmac in green neon trails, he disarmed the lead operative before the first shell casing hit the concrete.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (39, 5, 5.0, 'Stay at Your House', 20, TRUE, CURRENT_TIMESTAMP(), '<p>The warning sirens inside David''s optics were flashing amber, rapidly turning crimson. Cyberpsychosis symptoms—shaking fingers, blurred vision, phantom voices whispering from the cyberware.</p><p>He popped three immuno-blocker injectors directly into his neck, gasping as cold chemicals chilled his burning synapses. On the rooftop overlooking the city''s neon towers, Lucy wrapped her arms around his bulky, chromed frame.</p><p>"David, stop putting more chrome in," she pleaded, her voice trembling. "You don''t have to carry everyone''s dreams alone."</p><p>David kissed her forehead, smiling gently through the pain. "I promised you the moon, Lucy. Night City isn''t taking that away from us."</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (6, 'Tower of God', 'SIU', '/uploads/cover_tower_of_god.jpg', 'COMIC', 'Fantasy, Adventure, Action', 4.7, 'ONGOING', 1, 2020, 'Korea', 'Webtoon', 'Tower, Regulars, Shinsu, Male Lead, Mystery', FALSE, FALSE, 'What do you desire? Wealth? Glory? Power? Revenge? Whatever you desire is waiting at the pinnacle of the Tower. Bam, an Irregular youth who only sought to be reunited with his sole companion Rachel, opens the gates to face tests that challenge the gods themselves.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (14, 6, 1.0, '1F - Headon''s Floor', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Bam fell through the massive stone gate onto a platform surrounded by misty, bottomless waters. A tall creature with a rabbit-like mask and a glowing staff greeted him with an eerie grin.</p><p>"Welcome, boy, to the Tower," Headon spoke, his voice echoing with centuries of age. "All who enter desire something great. What is it that drives you&mdash;</p><p>"Rachel," Bam replied immediately, his golden eyes filled with desperate conviction. "She entered before me. I want to be where she is."</p><p>Headon chuckled softly. "Then you must pass the entrance exam: break the black ball caged inside the Steel Eel''s lair. An Irregular must show strength worthy of climbing."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (15, 6, 2.0, 'The Steel Eel & The Black March', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Before Bam could step into the steel cage, the arrival of Princess Yuri Zahard changed everything. Intrigued by an Irregular boy who did not tremble before monsters, she lent him the legendary needle: The Black March.</p><p>"Ignite it, boy!" Yuri called out from the observation deck.</p><p>As the massive armored serpent lunged with maw wide open, Bam thrust the needle forward. Shinsu flared around the blade in violet lightning, shattering the barrier in an explosive burst of pure energy.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (40, 6, 3.0, 'Floor of Tests: Crown Game', 10, TRUE, CURRENT_TIMESTAMP(), '<p>On Evankhell''s testing grounds, the Crown Game turned the grand arena into a battle royal of regular climbers. Sitting atop the gilded throne with the heavy ruby crown on his head, whoever held the seat for five rounds would bypass future tests completely.</p><p>Rak Wraithraiser brandished his prehistoric stone spear, shouting at the trembling competitors: "Come at us, turtles! Lord Rak will smash you all into turtle soup!"</p><p>Beside him, Khun Aguero Agnis leaned calmly against the armrest, tossing a golden coin between his fingers with a sly smirk. "Let them tire each other out first, Rak. A true strategist strikes only when the trap is sprung."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (41, 6, 4.0, 'The Lighthouse and the Spear', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Three floating yellow cubes hummed into formation around Khun. As a Light Bearer, his lighthouses gathered battlefield data, projecting holographic trajectories directly into Bam''s vision.</p><p>"Team from the right flank—three scouts armed with needle whips," Khun whispered into his earpiece. "Rak, spear at thirty-two degrees!"</p><p>With a seismic thunderclap, Rak''s spear shattered the arena wall, blowing the attackers off the stage. Watching from the shadows, test director Yu Han Sung sipped his instant coffee with an enigmatic smile: "That boy Bam... he manipulates Shinsu without signing a contract with the Administrator. An Irregular truly is a monster."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (42, 6, 5.0, 'The Position Test', 15, TRUE, CURRENT_TIMESTAMP(), '<p>The final exam for the second floor began in the submerged ruins. Wave Controllers were instructed to gather bangs of Shinsu to manipulate the flow of battle.</p><p>While other prodigies struggled to maintain two floating baangs of energy, Bam closed his eyes. The ambient Shinsu in the air responded not to force, but to his gentle presence, swirling into five crystalline orbs that lit up the ancient testing hall.</p><p>"Rachel is climbing ahead of me," Bam whispered, looking upward toward the artificial ceiling that simulated the open sky. "I don''t care how dangerous this tower is. I will reach her side."</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (7, 'The Beginning After The End', 'TurtleMe', '/uploads/cover_tbate.jpg', 'NOVEL', 'Fantasy, Action, Romance', 4.8, 'ONGOING', 1, 2022, 'USA', 'Web Novel', 'Reincarnation, Magic, Dragons, Mana Core, Academy', FALSE, FALSE, 'King Grey commanded unmatched authority, wealth, and martial prowess in a world ruled by combat. But behind the crown lay profound solitude. Reborn as Arthur Leywin in the magical continent of Dicathen, he resolves to protect his newfound family and forge true bonds.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (16, 7, 1.0, 'Early Awakening', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Being an infant with the memories of an undefeated sovereign king was an unusual experience. For the first two years of his life in the Ashber countryside, Arthur Leywin spent his time crawling toward the family library and meditating.</p><p>In this world, magic was governed by mana particles floating in the atmosphere. By drawing them into his sternum, Arthur gradually coalesced a nascent mana core. At age four, while attempting to compress the ambient mana, an explosive shockwave blew out the walls of his bedroom.</p><p>His parents rushed in terrified, only to find their four-year-old toddler sitting amid the debris, his aura radiating clear cerulean light. Arthur had awakened as a mage years before any recorded prodigy in Dicathen''s history.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (17, 7, 2.0, 'Mana Core Formation', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Rey and Alice Leywin were both accomplished former adventurers, but neither had ever witnessed a child forming a black-stage mana core at kindergarten age.</p><p>"He didn''t just awaken, Alice," Rey whispered, his jaw dropped. "His mana channels are as wide as a veteran knight''s!"</p><p>Arthur blinked innocently, offering a babyish giggle to defuse their panic. Yet in his heart, he made a solemn vow: <i>''In my past life, I lived for honor and died alone. In this life, I will use every ounce of my power to protect the warmth of this family.''</i></p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (43, 7, 3.0, 'Encounter in the Beast Glades', 10, TRUE, CURRENT_TIMESTAMP(), '<p>The merchant carriage expedition through the Grand Mountains was interrupted by a vicious bandit raid. Shadow panthers and rogue conjurers ambushed the caravan on a narrow cliffside ledge.</p><p>Seeing a spellblade''s poisoned blade lunging straight toward his pregnant mother Alice, four-year-old Arthur did not hesitate. Drawing on his former martial instincts, he tackled the attacker over the precipice, tumbling thousands of feet into the bottomless abyss below.</p><p>Falling through the thick fog, the expected fatal impact never came. A radiant golden barrier enveloped his body, gently carrying him into a hidden subterranean sanctuary bathed in lavender crystal light.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (44, 7, 4.0, 'The Elderwood Guardian', 10, TRUE, CURRENT_TIMESTAMP(), '<p>A colossal, magnificent dragon with scales that shimmered like polished obsidian lay curled within the crystal cavern. Sylvia—an ancient Asura of the dragon race.</p><p>"Fascinating child," Sylvia spoke, her voice resonant and warm like a lullaby. "A human infant carrying the seasoned soul of an old warrior. It seems fate has brought you to my sanctuary."</p><p>For the next three years, Sylvia became Arthur''s mentor, teaching him the profound differences between mana manipulation and the ancient, primordial art of Aether. In this timeless sanctuary, Arthur''s dark core purified into a brilliant orange stage.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (45, 7, 5.0, 'The Bonds of Sylvia', 15, TRUE, CURRENT_TIMESTAMP(), '<p>The peaceful years shattered when hostile black-horned demons breached the sanctuary''s spatial barrier. Sylvia transformed into her true dragon form, unleashing golden flames to shield Arthur.</p><p>"Art, take this stone," Sylvia whispered, pressing a rainbow-tinted dragon egg and a glowing rune into his sternum. "My will shall protect your core. Reconnect with the outside world... and find your own path."</p><p>A spatial portal opened beneath his feet. Transported to the outskirts of the Elshire forest, Arthur wiped tears from his eyes, clutching the precious dragon egg to his chest. His journey in Dicathen had truly begun.</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (8, 'Lord of the Mysteries', 'Cuttlefish That Loves Diving', '/uploads/cover_lotm.jpg', 'NOVEL', 'Mystery, Fantasy, Sci-Fi', 4.9, 'COMPLETED', 1, 2020, 'China', 'Web Novel', 'Steampunk, Victorian, Eldritch, Tarot Club, Beyonder', TRUE, FALSE, 'Amid the roar of steam engines and Victorian gas lamps, dark occult forces stir in the fog. Zhou Mingrui awakens in the body of Klein Moretti with a bullet hole through his temple. To unravel the mystery of his rebirth and ascend the Beyonder pathways, he founds the legendary Tarot Club.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (18, 8, 1.0, 'Crimson', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Pain surged through his skull like a white-hot poker. Klein Moretti sat up on a narrow cot in a modest rented room in Tingen City, clutching his temple.</p><p>On the wooden desk beside him lay a brass revolver, an ink-stained notebook with missing pages, and a cracked mirror. When he peered into the glass, he was horrified to find a neat, circular bullet wound on his left temple, dried crimson blood caking his dark hair.</p><p>And yet, he was breathing. The clock chimed midnight with a solemn metallic chime. As he recited an ancient luck-enhancement ritual in four steps counter-clockwise, the fabric of space sheared open, pulling his consciousness above the gray fog of eternity.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (19, 8, 2.0, 'The Fool and the Tarot Club', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Above the infinite sea of grayish-white fog stood an ancient divine palace supported by majestic stone pillars. Klein found himself seated at the head of a bronze long table.</p><p>With a wave of his hand, two shimmering stars in the crimson cosmos flared, projecting the illusory astral figures of a noble lady and a desperate young sailor.</p><p>"Who are you? Is this a secret orthodox ritual&mdash; the lady asked, trembling in awe before the divine sanctuary.</p><p>Klein leaned back into the shadows of the high-backed chair, steepling his fingers with enigmatic grace. "You may address me as... The Fool."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (46, 8, 3.0, 'Nighthawks of Tingen', 10, TRUE, CURRENT_TIMESTAMP(), '<p>At 36 Zouteland Street, behind the brass plaque of the Blackthorn Security Company, Klein stepped into the underground headquarters of the Church of the Evernight Goddess.</p><p>Captain Dunn Smith removed his black trench coat, his deep gray eyes scrutinizing Klein with calm scrutiny. "Mr. Moretti, ordinary citizens who survive suicide by supernatural firearms either lose their minds or attract unspeakable horrors. You seem remarkably coherent."</p><p>"I wish to understand the truth behind the notebook, Captain," Klein replied evenly. Dunn Smith smiled faintly, pouring two cups of aromatic southern coffee. "Then welcome to the Nighthawks, Klein. We are guardians, but also a bunch of miserable wretches constantly fighting against madness."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (47, 8, 4.0, 'The Seer Potion', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Inside the underground alchemy chamber, Klein prepared the formula for Sequence 9: Seer. 100 milliliters of pure water, five drops of lavary juice, 7 grams of black-spotted grass powder, and the primary ingredients: 10 milliliters of mutated fish blood and a stalk of lavender from the Hornacis mountain peak.</p><p>The liquid turned a shimmering deep purple, swirling like a tiny galaxy within the crystal beaker. Taking a deep breath, Klein downed the bitter concoction in a single gulp.</p><p>His vision fractured into a thousand shimmering colors. The aura of objects, the emotions of living beings, and the invisible spirit threads connecting the universe unfolded before his eyes. He had officially stepped onto the path of the Beyonder.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (48, 8, 5.0, 'Clown and Marionette', 15, TRUE, CURRENT_TIMESTAMP(), '<p>The Antigonus family notebook had resurfaced in an abandoned clown workshop in the eastern slums. The air reeked of ozone and decaying flesh.</p><p>A Beyonder rampager covered in wooden marionette joints sprang from the rafters, razor-sharp strings whistling toward Klein''s throat. Klein flicked his wrist: a playing card—The Magician—whistled through the air wrapped in holy silver flame, cleanly severing the strings.</p><p>"A magician never performs unprepared," Klein murmured, drawing his brass revolver. With three rhythmic shots echoing through the rainy night, the corrupted rampager dissolved into white ash, leaving behind a crystalline beyonder characteristic that pulsed like a miniature heart.</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (9, 'Shadow Slave', 'Guiltythree', '/uploads/cover_shadow_slave.jpg', 'NOVEL', 'Fantasy, Action, Mystery', 4.8, 'ONGOING', 1, 2023, 'International', 'Web Novel', 'Nightmare Spell, Shadows, Forgotten Shore, Treacherous Lead', FALSE, FALSE, 'Growing up as an impoverished street rat in the outskirts of the outskirts, Sunny had zero ambition beyond surviving another winter. But when infected by the Nightmare Spell, he is transported into an ancient fallen realm where monsters roam, unlocking a divine shadow aspect with a treacherous curse.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (20, 9, 1.0, 'Nightmare Spell', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Sunny had spent his sixteen years of life learning how to be invisible. In the impoverished outskirts of N5, being noticeable got you mugged, beaten, or harvested for organs.</p><p>So when the black markings of the Nightmare Spell began spiraling across his collarbone, he didn''t cry or pray. He just sighed and stole two cans of synth-meat from the corner store. If he was going to fall into a comatose trial and die, he might as well die on a full stomach.</p><p>That night, reality dissolved into an endless blizzard on a mountain peak. The mechanical whisper of the Spell echoed in his mind: <i>''Aspirant, welcome to your First Nightmare.''</i></p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (21, 9, 2.0, 'The Mountain King', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The wind howled like a pack of wolves, freezing the blood in Sunny''s veins. He was chained to a wooden post inside a sacrificial caravan, surrounded by shivering slaves.</p><p>Through the blizzard, two crimson searchlights opened in the crags above. A Mountain King—a colossal centipede-like abomination plated with black ice—descended toward the helpless humans.</p><p>Sunny didn''t scream like the others. He carefully slipped his frostbitten thumb out of the iron cuff. "Fools die honorably," Sunny muttered through chattering teeth. "Cowards live to tell the tale."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (49, 9, 3.0, 'The Ashen Barrow', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Luring the monstrous Mountain King onto the rotten rope bridge, Sunny severed the anchor fibers with a rusty slave pickaxe. With a thunderous crack, the colossal ice tyrant plunged screaming into the bottomless abyss.</p><p><b>[You have slain an Awakened Tyrant: Mountain King.]</b><br><b>[Your trial evaluation: Glorious.]</b><br><b>[Aspect Acquired: Shadow Slave (Divine)]</b><br><b>[True Name Received: Lost from Light.]</b><br><b>[Flaw: Clear Conscience — You are physically incapable of telling a lie.]</b></p><p>Sunny collapsed onto the snow, laughing hysterically. "A Divine aspect? Fantastic! But a flaw that forbids lying? In this cursed world, that''s practically a death sentence!"</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (50, 9, 4.0, 'The Sea of Darkness', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Awakening in the real world only to be teleported into the dream realm of the Forgotten Shore, Sunny found himself standing upon the ruins of a submerged labyrinth.</p><p>Twice a day, the crimson sun sank below the horizon, and the black sea rose by hundreds of feet, swallowing everything. From the depths of the obsidian water, ancient eldritch leviathans drifted like moving islands.</p><p>His own shadow detached from his boots, standing upright with crossed arms and a mocking shrug. "Oh great, now my shadow has an attitude," Sunny muttered, retreating to a high stone battlement before the tide swallowed the cobblestones.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (51, 9, 5.0, 'The Nameless Temple', 15, TRUE, CURRENT_TIMESTAMP(), '<p>In the ruins of the Sun God''s ancient temple, Sunny encountered two fellow Sleeper survivors: Nephis, the silver-haired scion of the Immortal Flame clan, and Cassie, a frail blind girl whose aspect granted precognitive visions.</p><p>"You fight like someone who expects to be stabbed in the back," Nephis observed, wiping black blood from her glowing silver sword.</p><p>"I grew up in the outskirts," Sunny replied smoothly, his shadow silently watching the perimeter for drowned abominations. "Paranoia is just common sense with better survival rates."</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (10, 'Super Cub', 'Tone Koken', '/uploads/cover_super_cub.jpg', 'MANGA', 'Slice of Life', 4.8, 'COMPLETED', 1, 2021, 'Japan', 'Light Novel', 'Motorbikes, School Life, Peaceful, Solitude', FALSE, FALSE, 'Koguma, a quiet second-year high school student in Yamanashi with no parents, friends, or hobbies, buys a pre-owned Honda Super Cub for ten thousand yen. The little motorized scooter quietly expands her horizons, bringing gentle adventures and lifelong companionship.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (22, 10, 1.0, 'The Pre-owned Super Cub', 0, TRUE, CURRENT_TIMESTAMP(), '/uploads/604f9929-1464-441b-af14-3149ba91a05a.png,/uploads/5843a4ab-08f5-4324-a663-030a28146b3d.png,/uploads/f1bf2da9-b171-47de-9467-6cd93c8205c1.png,/uploads/49dd87d7-6727-4b49-b5e0-7424ffd8e405.png,/uploads/199d78c6-ac19-4b90-a905-6bd1a59ea708.png,/uploads/96131cf8-91f5-41fd-99bc-78f235135bca.png,/uploads/608d5d4e-0f56-4efc-b6ea-6dfaee7aafeb.png,/uploads/dbcf04ee-789a-4ac4-8033-fd7cb874503f.png,/uploads/6a4944a2-d625-475d-beca-105381e1b7ae.png,/uploads/9dd61a36-5ed3-4416-ade4-e62f92ee5a38.png');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (23, 10, 2.0, 'Morning Commute', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The gentle hum of the 50cc four-stroke engine resonated through the morning air of Hokuto. Koguma adjusted her retro helmet, feeling the cool mountain breeze on her cheeks.</p><p>For the first time in her life, the monotonous uphill bicycle ride to school was replaced by the smooth glide of two wheels. She stopped at the traffic light, her hands resting comfortably on the black rubber handlebars. When a classmate noticed her at the bike rack, a hesitant smile broke across Koguma''s face—her world was finally starting to grow.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (52, 10, 3.0, 'A Box for the Rear Rack', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Carrying groceries and heavy textbooks in a backpack was tiring during long rides. After school, Koguma stopped by the local credit union where an old delivery worker was replacing a faded fiberglass rear storage box.</p><p>"You want this old thing, kid&mdash; the worker asked, dusting off the sturdy white box. "It''s got a few scratches, but the lock still clicks tight."</p><p>With a set of newly purchased wrenches from the hardware store, Koguma carefully bolted the box onto her Super Cub''s steel luggage rack. As she clicked the latch shut with a thermos of hot tea inside, the little motorcycle felt less like a machine and more like a dependable companion for any adventure.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (53, 10, 4.0, 'Riding in the Autumn Rain', 15, TRUE, CURRENT_TIMESTAMP(), '<p>The autumn clouds rolled over Mount Fuji without warning, unleashing a sudden downpour along Route 20. Raindrops drummed against Koguma''s yellow vinyl raincoat.</p><p>On a bicycle, this rain would have meant soaked shoes and miserable exhaustion. But astride her Super Cub, with the leg shields deflecting the puddle spray and the headlight cutting through the mist, she felt completely secure. Pulling under the eaves of an old roadside convenience store, she took a sip of warm canned coffee, listening to the peaceful sound of raindrops on tin roofs.</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (11, 'Chainsaw Man', 'Tatsuki Fujimoto', '/uploads/cover_chainsaw_man.png', 'MANGA', 'Action, Fantasy, Horror', 4.8, 'ONGOING', 1, 2022, 'Japan', 'Manga', 'Devils, Chainsaw, Public Safety, Dark Comedy, Action', FALSE, FALSE, 'Denji lives in squalor, drowning in his deceased father''s debts to the yakuza and hunting devils alongside Pochita, the canine Chainsaw Devil. After a brutal ambush leaves them diced to pieces, Pochita merges into Denji''s heart, awakening the ferocious Chainsaw Man.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (24, 11, 1.0, 'Dog & Chainsaw', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Denji''s dream was simple: jam on toast, video games with Pochita, and holding hands with a girl before he died. Instead, he lived in a leaky shed eating cigarette butts on a dare for loose change.</p><p>Pochita, a dog with a whirring saw blade emerging from his forehead, whimpered affectionately as Denji chopped firewood. "Don''t worry, buddy," Denji smiled weakly, coughing blood. "We''ll pay off this debt someday."</p><p>That night, the yakuza boss lured them into an abandoned warehouse under the guise of an extermination job. But the warehouse was a slaughterhouse ruled by the Zombie Devil. Betrayed and hacked to pieces, Denji''s severed hand brushed against Pochita''s wound, sealing their eternal pact.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (25, 11, 2.0, 'A Place Where Dreams Come True', 0, TRUE, CURRENT_TIMESTAMP(), '<p><i>''Denji... I loved hearing you talk about your dreams,''</i> Pochita''s voice resonated in the void. <i>''In exchange for my heart... show me your dreams.''</i></p><p>Denji''s eyes snapped open amid the blood-drenched heaps. A starter cord dangled from the center of his chest. He gripped the handle and pulled back hard.</p><p><b>*VVRRRRRRRRRRRRRRRRRRRRRRR!*</b></p><p>Twin chainsaws erupted from his forearms, while a vicious armored blade ripped through his skull. The slaughter of the Zombie horde began, heralding the birth of Chainsaw Man.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (54, 11, 3.0, 'Arrival at Public Safety Tokyo', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Tokyo was blindingly bright compared to the countryside slums. In the sleek headquarters of Public Safety Devil Extermination Division 4, Makima handed Denji a clean white shirt, a black necktie, and an official badge.</p><p>"From today, Denji, you are an official Devil Hunter," Makima smiled, her golden ringed eyes carrying an unnerving aura of gentle hypnosis. "Your senior partner will be Aki Hayakawa."</p><p>Aki took one look at Denji''s slouching posture, unkempt blond hair, and wide grin. In the alleyway behind the precinct, Aki knocked Denji against the brick wall: "You don''t care about justice, and you don''t fear devils. People like you end up dead in their first week. Quit and go home." Denji simply kicked him back with a cackle: "I''m finally eating three meals a day, pal! You think a punch is gonna make me quit&mdash;</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (55, 11, 4.0, 'The Blood Fiend Power', 10, TRUE, CURRENT_TIMESTAMP(), '<p>A loud crash echoed in the squad car as a girl with long strawberry blond hair and crimson horns kicked open the door, holding a terrified stray pigeon by its legs.</p><p>"Bow before me, mortals! I am Power, the Blood Fiend!" she shouted, pointing an arrogant finger at the sky. "All humans exist merely to serve as nourishment for my magnificence!"</p><p>Denji stared at her in disbelief, turning to Aki: "Are all your recruits completely unhinged&mdash; Power snatched Denji''s sandwich, took a massive bite, and shoved him into the back seat: "Shut up, dog! We are going hunting!"</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (56, 11, 5.0, 'Bat Devil Extermination', 15, TRUE, CURRENT_TIMESTAMP(), '<p>At the abandoned residential complex outside the city, the grotesque Bat Devil hovered above the broken roof tiles, holding Power''s pet cat Meowy hostage in its claws.</p><p>"Hand over the boy, blood fiend, and I might spare your miserable kitten!" the beast shrieked, swatting Power into a brick wall.</p><p>Denji didn''t hesitate. Pulling the rip cord in the center of his chest, the roar of the two-stroke engine drowned out the storm. Leaping eighty feet into the sky, Chainsaw Man sank both spinning arm blades directly into the Bat Devil''s snout, tearing through flesh and bone in a neon explosion of crimson rain.</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (12, 'Spy x Family', 'Tatsuya Endo', '/uploads/cover_spy_x_family.jpg', 'MANGA', 'Comedy, Action, Slice of Life', 4.8, 'COMPLETED', 1, 2021, 'Japan', 'Manga', 'Spy, Telepath, Assassin, Wholesome Family, Comedy', TRUE, FALSE, 'Master spy Twilight must assemble a phony family within seven days to infiltrate an exclusive social gathering at Eden Academy. He adopts Anya, an orphaned telepath, and marries Yor, a soft-spoken city hall clerk who moonlights as the lethal assassin Thorn Princess.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (28, 12, 1.0, 'Mission 1: Operation Strix', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Agent Twilight had assumed a thousand identities: diplomat, doctor, thief, soldier. But his newest top-secret mission for WISE was unprecedented: get married and enroll a child in Eden Academy within seven days.</p><p>At a decrepit orphanage in Ostania, he found Anya—a pink-haired little girl sitting quietly with a crossword puzzle. Unbeknownst to Twilight, Anya was a telepath who had escaped a secret government lab.</p><p>Hearing his thoughts—<i>''I need a child who can read and write to pass the admissions test''</i>—Anya swiftly filled out the puzzle by reading his mind. "Anya is very smart!" she declared with wide, sparkly eyes. "Take Anya home!"</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (29, 12, 2.0, 'Mission 2: Secure a Wife', 0, TRUE, CURRENT_TIMESTAMP(), '<p>With Anya adopted, the second hurdle proved even more daunting: Eden Academy required both parents to attend the formal entrance interview.</p><p>At a local tailor shop, Twilight crossed paths with Yor Briar, a graceful twenty-seven-year-old clerk looking for a fake boyfriend to quiet her co-workers'' suspicious questions. Hearing Yor''s secret thoughts—<i>''I must avoid drawing police attention to my assassin work as Thorn Princess''</i>—Anya beamed with utter delight.</p><p>"Anya wants a pretty mama!" she chimed in, grabbing both their hands. And thus, the world''s most dangerous and wholesome faux family was born.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (57, 12, 3.0, 'The Rigorous Family Interview', 10, TRUE, CURRENT_TIMESTAMP(), '<p>The imposing stone gates of Eden Academy were designed to intimidate all who entered. Even the trees seemed manicured to inspect candidates for lack of elegance.</p><p>When a herd of escaped zoo animals stampeded through the courtyard toward a frightened toddler, Twilight sprang into action. But before he could draw his sedative pen, Yor stepped forward, delivering a pinpoint acupuncture strike to the lead cow''s pressure points, gently subduing the beast.</p><p>"ELEGANT! UTTERLY ELEGANT!" Housemaster Henry Henderson gasped from the headmaster''s balcony, his monocle nearly popping off in sheer admiration. In the interview room that followed, the Forger family handled every absurd question with poised wit and genuine warmth.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (58, 12, 4.0, 'Stella Stars and Peanuts', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Anya''s first week in Cecile Hall was an uphill battle. Learning arithmetic and classical languages was boring, and Damian Desmond—the arrogant son of Twilight''s target Donovan Desmond—constantly called her ''stumpy''.</p><p>"If I punch him, Papa''s world peace plan will go boom," Anya thought, recalling Twilight''s panicked internal monologues. Instead, she offered Damian a smug, half-lidded smirk that left the young heir flustered and speechless.</p><p>Later that afternoon at the school pool, Anya heard a drowning boy''s distressed thoughts: <i>''Help... I can''t breathe!''</i> Diving into the water without hesitation, she pulled him to safety, earning Eden Academy''s prestigious Stella Star and a mountain of crispy roasted peanuts from Twilight.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (59, 12, 5.0, 'Project Apple: The Big White Dog', 15, TRUE, CURRENT_TIMESTAMP(), '<p>While attending an adoption fair to reward Anya for her Stella Star, Anya brushed past a massive, fluffy Great Pyrenees dog with intelligent amber eyes.</p><p>Instantly, Anya''s mind connected with the dog''s precognitive vision: a clock tower exploding, and Twilight lying crushed beneath debris! The dog was a former test subject of the defunct military research Project Apple, capable of seeing seconds into the future.</p><p>"Borf!" the big white dog barked, nudging Anya onto his back. With Anya gripping his thick white fur, the duo dashed through the streets of Berlint to intercept the terrorist bomb timer, saving Twilight just in the nick of time. Naming him ''Bond'' after her favorite spy cartoon hero, the Forger family grew by four paws.</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (13, 'Mushoku Tensei: Jobless Reincarnation', 'Rifujin na Magonote', '/uploads/cover_mushoku_tensei.jpg', 'NOVEL', 'Fantasy, Adventure, Isekai', 4.9, 'ONGOING', 1, 2021, 'Japan', 'Light Novel', 'Reincarnation, Magic, Growth, World Travel, Fantasy, Academy', TRUE, FALSE, 'Reincarnated into a swords-and-sorcery realm with full memories of a wasted past, Rudeus Greyrat vows to live his new life to the absolute fullest without regrets. Mastering silent magic from toddlerhood under Roxy Migurdia, he sets forth on a magnificent journey spanning kingdoms and continents.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (60, 13, 1.0, 'The Second Chance', 0, TRUE, CURRENT_TIMESTAMP(), '<p>A thirty-four-year-old shut-in, thrown out into the freezing rain after his parents'' funeral, had pushed a high school student out of the way of a speeding truck. He expected eternal nothingness. Instead, he opened his eyes to find a wooden ceiling and a gentle mother with chestnut hair smiling down at him.</p><p>He was reincarnated as Rudeus Greyrat, the infant son of the swordsman Paul and former healer Zenith in the peaceful village of Buena.</p><p>Determined not to repeat the laziness that had ruined his previous existence, young Rudeus crawled out of his crib each afternoon to study his mother''s heavy grimoires. Discovering that mana flow responded to concentration rather than verbal incantations, he successfully cast an Intermediate Water Ball silently at the tender age of three.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (61, 13, 2.0, 'The Water-Saint Magician Roxy', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Realizing their son was a once-in-a-century prodigy, Paul and Zenith hired a private tutor: Roxy Migurdia, a petite Water-Saint magician from the Migurd demon race with braided blue hair and a quiet, deadpan manner.</p><p>Roxy initially doubted the parents'' claims, but after witnessing Rudeus cast silent water spells and combine earth magic to sculpt miniature statues, she realized she had taken on a monster of talent.</p><p>On his fifth birthday graduation exam, Roxy led Rudeus on horseback beyond the village borders—a place he had feared to go due to childhood trauma. Under the pouring thunderclouds, Roxy demonstrated the majestic Water-Saint spell ''Cumulonimbus'', curing Rudeus''s agoraphobia and inspiring him to seek the vast horizons of the world.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (62, 13, 3.0, 'The Violent Red-Haired Heiress Eris', 10, TRUE, CURRENT_TIMESTAMP(), '<p>To earn tuition funds for both himself and his childhood friend Sylphiette to attend the Ranoa Magic Academy, Rudeus accepted a tutoring position in the fortress city of Roa.</p><p>His student was Eris Boreas Greyrat: a fierce, red-haired young noble girl whose temper was legendary. Within five minutes of their first meeting, she delivered a ferocious punch straight to Rudeus''s jaw.</p><p>Realizing that normal discipline would never work, Rudeus devised a staged kidnapping scenario with the family guards to teach Eris humility and mutual trust. When actual rogue assassins intercepted the carriage, Rudeus fought with lethal earth spears, saving Eris''s life and forging an unbreakable bond of loyalty.</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (14, 'Jujutsu Kaisen', 'Gege Akutami', '/uploads/cover_jujutsu_kaisen.jpg', 'MANGA', 'Action, Supernatural, Fantasy', 4.9, 'COMPLETED', 1, 2020, 'Japan', 'Manga', 'Cursed Spirits, Jujutsu Sorcerers, Sukuna, Domain Expansion, Action', TRUE, FALSE, 'High school athlete Yuji Itadori swallows a rotten finger belonging to Ryomen Sukuna—the King of Curses—to save his friends from a demonic curse. Thrust into Tokyo Jujutsu High under the enigmatic Satoru Gojo, Yuji embraces the burden of hunting the remaining fingers before his inevitable execution.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (63, 14, 1.0, 'Ryomen Sukuna', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Sugisawa High School was pitch black at night. Inside the club room, the Occult Club members were gleefully peeling off the sealing talismans from a dried, mummified human finger they had found in a weather thermometer shelter.</p><p>A horrific, grotesque cursed spirit descended through the ceiling tiles, its dozen insectoid arms smashing the desks. First-year sorcerer Megumi Fushiguro arrived with his twin Divine Dog shikigami, but the curse''s miasma was overwhelming.</p><p>Bursting through the fourth-floor glass window with athletic superhuman speed, Yuji Itadori tackled the curse. Cornered and desperate to save his friends, Yuji stared at the talisman finger in his hand. With reckless resolve, he shoved the dried flesh down his throat. Black tribal markings ignited across his skin, and the terrifying King of Curses, Ryomen Sukuna, awoke after a thousand years.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (64, 14, 2.0, 'Secret Execution', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Yuji awoke bound to a wooden chair in a circular basement chamber lined with hundreds of sacred sealing talismans. Leaning casually against the pillar was a tall man with spiky white hair and a pitch-black blindfold: Satoru Gojo.</p><p>"Good morning, Yuji!" Gojo smiled cheerfully. "You are currently sentenced to a secret execution by the higher-ups of the Jujutsu world."</p><p>Before Yuji could panic, Gojo explained the situation: as a one-in-a-million vessel capable of suppressing Sukuna''s consciousness, Yuji could either die immediately, or consume all twenty of Sukuna''s fingers scattered across Japan so the curse could be destroyed once and for all. Yuji looked down at his grandfather''s memory: <i>''Use your strength to help others.''</i> With a firm nod, Yuji chose the path of the sorcerer.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (65, 14, 3.0, 'For Myself', 10, TRUE, CURRENT_TIMESTAMP(), '<p>At the secluded mountain campus of Tokyo Jujutsu High, Principal Masamichi Yaga sat in the entrance hall surrounded by knit cursed corpse dolls.</p><p>"Why do you wish to become a Jujutsu sorcerer, Itadori&mdash; Principal Yaga asked sternly. When Yuji answered that it was because of his grandfather''s dying wish, Yaga shook his head: "Rejected."</p><p>A heavy boxing cursed doll sprang from the shadows, pummeling Yuji across the tatami mats. Dodging the crushing blows, Yuji searched deep within his soul: "If I turn away now when I have the power to save someone from being consumed by a curse, I would never be able to forgive myself! I want to live so I have no regrets!" Satisfied with his true resolve, Yaga smiled: "You pass. Welcome to Jujutsu High."</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (15, 'Classroom of the Elite', 'Shougo Kinugasa', '/uploads/cover_classroom_of_the_elite.jpg', 'NOVEL', 'Psychological, Drama, Mystery', 4.8, 'ONGOING', 1, 2022, 'Japan', 'Light Novel', 'Tokyo Advanced High, Class D, Genius Mastermind, White Room, Strategy', TRUE, FALSE, 'Tokyo Metropolitan Advanced Nurturing High School boasts a 100% employment rate and grants students luxury allowances of 100,000 points. But behind the glamorous facade lies a brutal meritocratic battlefield where Class D discovers that laziness brings instant financial ruin. Kiyotaka Ayanokoji quietly orchestrates everything from the shadows.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (66, 15, 1.0, 'What is Evil? Whatever Springs from Weakness', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The morning bus to the Tokyo Metropolitan Advanced Nurturing High School was crowded with new students in crimson blazers. When an elderly woman boarded the bus with difficulty, an argument erupted over priority seating.</p><p>Sitting near the window, Kiyotaka Ayanokoji observed the exchange in silence. Beside him sat Suzune Horikita, an unapproachable girl reading a dense paperback who bluntly refused to surrender her seat on logical grounds.</p><p>Upon arriving at the pristine campus, the students received digital student IDs loaded with 100,000 points—equivalent to 100,000 yen each month. While his classmates celebrated their newfound wealth by buying video games and gourmet meals, Ayanokoji sensed that nothing provided by the government was ever truly free.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (67, 15, 2.0, 'Class D and the S-System', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The first of May arrived with a cruel awakening. When the students checked their digital balances on the classroom terminals, their monthly deposit read exactly zero points.</p><p>Panic and outrage swept through Class D. Their homeroom teacher, Sae Chabashira, stepped up to the podium with a cold, mocking smirk. She tapped the blackboard, displaying a breakdown of every missed homework assignment, whisper during lectures, and tardy arrival recorded over the past month.</p><p>"This school evaluates students on total merit under the S-System," Chabashira explained. "Class D is the dumping ground for defective students. If your class points hit zero, your allowance remains zero. And anyone who fails the upcoming midterm exam will be immediately expelled."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (68, 15, 3.0, 'The White Room''s Masterpiece', 10, TRUE, CURRENT_TIMESTAMP(), '<p>With several delinquent students like Ken Sudo on the verge of failing with single-digit test averages, Horikita''s study sessions collapsed in frustration.</p><p>Quietly slipping away from the dorms, Ayanokoji tracked down a third-year upperclassman in the cafeteria. Offering 15,000 personal points, he purchased a physical copy of the previous year''s midterm examination questions. Because teachers rarely reinvented standardized tests, the mock test covered ninety percent of the actual material.</p><p>Handing the study guide to the class while letting Kushida take all the credit, Ayanokoji returned to his desk, adjusting his collar. In his mind, people were nothing more than tools to ensure his peaceful, quiet existence.</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (16, 'Overlord', 'Kugane Maruyama', '/uploads/cover_overlord.jpg', 'NOVEL', 'Dark Fantasy, Action, Isekai', 4.9, 'ONGOING', 1, 2020, 'Japan', 'Light Novel', 'Undead Sovereign, Nazarick, Floor Guardians, Overpowered, Dark Fantasy', TRUE, FALSE, 'When the legendary MMORPG YGGDRASIL shuts its servers down, guild master Momonga decides to stay online until the final second. Instead of logging out, the Great Tomb of Nazarick is transported into a mysterious fantasy continent, and Momonga becomes his skeletal undead avatar, Ainz Ooal Gown.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (69, 16, 1.0, 'The End and the Beginning', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The digital clock in the corner of Momonga''s vision read 23:59:45. The dive-MMORPG YGGDRASIL was about to terminate its twelve-year service forever.</p><p>Sitting alone upon the Throne of Kings in the heart of the Great Tomb of Nazarick, Momonga held the Staff of Ainz Ooal Gown, reminiscing on the forty-one guild members who had once built this majestic underground empire.</p><p>00:00:00 ticked past. The forced logout sequence did not appear. Momonga opened his skeletal jaw, noticing the scent of burning incense and the smooth texture of the gold throne. More shockingly, the NPC overseer Albedo stepped forward, blushing with genuine affection: "Lord Momonga, is something amiss&mdash; The virtual game had transformed into living reality.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (70, 16, 2.0, 'Floor Guardians of the Great Tomb', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Momonga commanded a meeting on the sixth floor''s colossal Roman colosseum. One by one, the Floor Guardians arrived through teleportation gates: the silver-haired true vampire Shalltear Bloodfallen, the demonic strategist Demiurge, the four-armed frost insect Cocytus, and the dark elf twins Aura and Mare.</p><p>Kneeling in absolute devotion before their creator, each Guardian declared their unwavering allegiance to the supreme ruler of Nazarick.</p><p>Testing his magical capabilities, Momonga confirmed that all his 718 spells and super-tier magic remained fully functional. Assuming the name of his former guild, he declared: "From this moment forward, I am Ainz Ooal Gown. Spread the name of Nazarick across this new world!"</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (71, 16, 3.0, 'The Battle of Carne Village', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Through the Mirror of Remote Viewing, Ainz observed a peaceful human hamlet named Carne Village being raided by armored knights bearing the insignia of the Slane Theocracy.</p><p>Villagers were being systematically slaughtered. Remembering his former guildmate Touch Me, who lived by the motto of saving the weak, Ainz stepped through a gate directly onto the burning village square.</p><p>Drawing on his 9th-tier death magic, Ainz pointed a bony finger at the charging knight squadron: <b>[Grasp Heart]</b>. The captain''s chest crushed in mid-stride, dying instantly. To the trembling villagers, the towering skeletal overlord was both a terrifying nightmare and their sole divine savior.</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (17, 'That Time I Got Reincarnated as a Slime', 'Fuse', '/uploads/cover_slime.jpg', 'NOVEL', 'Fantasy, Adventure, Comedy', 4.8, 'ONGOING', 1, 2021, 'Japan', 'Light Novel', 'Slime, Predator Skill, Great Sage, Monster Nation, Nation Building', TRUE, FALSE, 'Staged corporate worker Satoru Mikami is stabbed by a passing mugger and reincarnated into a cave as a gelatinous blue slime with the Unique Skills ''Predator'' and ''Great Sage''. After befriending the imprisoned Storm Dragon Veldora, Rimuru Tempest sets forth to build a harmonious federation of monsters.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (72, 17, 1.0, 'Reincarnated in the Sealed Cave', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Protecting his junior colleague from a deranged knifeman on a Tokyo street corner, thirty-seven-year-old bachelor Satoru Mikami bled out on the pavement. In his final moments, a calm, mechanical voice translated his dying thoughts into intrinsic magical attributes.</p><p>When he regained consciousness, he had no eyes, no ears, and no limbs. He was a soft, gelatinous sphere of blue slime bouncing inside an underground cavern.</p><p>Through the guidance of his Unique Skill [Great Sage], he discovered his second Unique Skill: [Predator], capable of devouring materials and analyzing their properties. Absorbing rare magicule-rich hipokute herbs and magic ore, the little slime became an alchemical powerhouse in secret.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (73, 17, 2.0, 'Friendship with the Storm Dragon Veldora', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Deep within the cave, the slime bumped into a colossal wall of roaring spiritual pressure: Veldora the Storm Dragon, one of the four True Dragons of the world, imprisoned three hundred years ago by the Unlimited Imprisonment barrier of a human Hero.</p><p>Despite his terrifying draconic appearance, Veldora was deeply lonely and loved to boast about his past glory. Using telepathic magic taught by the dragon, the slime and the ancient dragon became fast friends.</p><p>To help Veldora analyze the barrier from within, the slime swallowed the entire sealed prison using [Predator], storing the dragon safely inside his stomach dimension. Before departing, they exchanged names: the dragon gave him the name ''Rimuru'', and together they adopted the shared family name ''Tempest''.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (74, 17, 3.0, 'Naming the Goblin Tribe', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Exiting the sealed cave into the lush Great Forest of Jura, Rimuru encountered a terrified tribe of diminutive goblins. Their chieftain Rigurd knelt before the gelatinous slime, begging for salvation against a pack of bloodthirsty direwolves.</p><p>Rimuru effortlessly defeated the direwolf alpha, absorbing its corpse to unlock the [Menace] skill, which caused the remaining wolves to submit peacefully. Resolving to bring order to both species, Rimuru began bestowing names upon every goblin and wolf.</p><p>What Rimuru didn''t realize was that naming monsters consumes immense quantities of mana. After naming over a hundred monsters, Rimuru fell into a comatose sleep. When he awoke three days later, the frail goblins had evolved into muscular, towering hobgoblins, and the wolves into giant tempest star wolves!</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (18, 'Re:Zero - Starting Life in Another World', 'Tappei Nagatsuki', '/uploads/cover_re_zero.jpg', 'NOVEL', 'Dark Fantasy, Psychological, Isekai', 4.9, 'ONGOING', 1, 2021, 'Japan', 'Light Novel', 'Return by Death, Witch Cult, Emilia, Rem, Psychological, Time Loop', TRUE, FALSE, 'Stepping out of a Tokyo convenience store, ordinary youth Subaru Natsuki is suddenly summoned into the royal capital of Lugnica. Possessing neither divine swords nor grand magic, his sole granted ability is ''Return by Death''—the agonizing power to rewind time upon each gruesome demise to save those he loves.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (75, 18, 1.0, 'The End of the Beginning and the Beginning of the End', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Subaru blinked against the blinding afternoon sun. He was wearing his gray tracksuit, holding a plastic convenience store bag with potato chips and instant noodles. Around him walked demi-humans with lizard tails, cat ears, and carriages pulled by giant ground dragons.</p><p>Thinking he had been blessed with standard protagonist cheat powers, he wandered into a secluded alley, only to be cornered and beaten by three street thugs.</p><p>Just as a dagger was drawn, a breathtaking young woman with silver hair and amethyst eyes appeared at the alley entrance, accompanied by a small floating gray cat spirit named Puck. With crystalline ice magic, she drove the thugs away. Grateful for her kindness, Subaru vowed to help her find the precious insignia stolen by a nimble blonde thief named Felt.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (76, 18, 2.0, 'Return by Death', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Following Felt''s trail to a dilapidated loot house in the capital slums, Subaru pushed open the heavy wooden door. The room was deathly quiet, reeking of fresh blood.</p><p>Stepping onto the floorboards, his hand brushed against something warm and sticky: the butchered corpse of Old Rom. Before Subaru could scream, a woman clad in revealing black leather—the assassin Elsa Granhiert—emerged from the shadows, slicing through Subaru''s stomach in a flash of curved steel.</p><p>Subaru collapsed in agony, his vision fading to black as his intestines spilled onto the cold stone. Suddenly, a violent gasp tore through his lungs. He was standing upright in the bustling market square, right in front of the green-haired fruit vendor he had spoken to three hours earlier. Time had completely reset.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (77, 18, 3.0, 'The Silver-Haired Half-Elf', 10, TRUE, CURRENT_TIMESTAMP(), '<p>After dying three agonizing deaths to the Bowel Hunter, Subaru realized the horrifying nature of his reality: he had no combat talents, no mana reserves, and every loop carried the visceral memory of death.</p><p>In the fourth loop, he adjusted his strategy. Sprinting through the commercial district, he crossed paths with the red-haired Sword Saint, Reinhard van Astrea, and alerted him to the illegal black market transaction in the slums.</p><p>When Elsa lunged toward Emilia inside the loot house, Reinhard burst through the wall, drawing a simple dragon sheath. With a single swing of pure atmospheric pressure, Reinhard obliterated the entire building structure, driving Elsa away and ensuring that for the first time, Emilia''s gentle smile survived until morning.</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (19, 'Vinland Saga', 'Makoto Yukimura', '/uploads/cover_vinland_saga.jpg', 'MANGA', 'Historical, Action, Adventure', 4.9, 'ONGOING', 1, 2020, 'Japan', 'Manga', 'Vikings, Thorfinn, Revenge, Historical War, Swordsmanship', TRUE, FALSE, 'Young Thorfinn grows up raised by the Viking mercenary band that murdered his father, the legendary Troll of Jom Thors. Driven solely by his burning thirst for a fair duel of vengeance against the cunning leader Askeladd, Thorfinn fights on blood-soaked battlefields across England while searching for the peaceful paradise called Vinland.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (78, 19, 1.0, 'Somewhere Not Here', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The icy winds of northern Iceland whistled through the timber longhouse. Sitting beside the hearth fire, young Thorfinn listened wide-eyed as the seasoned sailor Leif Erikson spoke of his voyage across the western sea.</p><p>"Beyond the storm-tossed waves lies a land called Vinland," Leif smiled, showing Thorfinn a dried cluster of sweet wild grapes. "The soil is warm, forests stretch without end, and neither king nor chieftain demands taxes or war. It is a land of peace."</p><p>To a boy whose world was defined by frost and barren soil, Vinland was paradise. His father Thors, a retired commander of the elite Jomsvikings who had cast his blade into the sea to live as a peaceful farmer, looked upon his son with quiet tenderness.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (79, 19, 2.0, 'The True Warrior', 0, TRUE, CURRENT_TIMESTAMP(), '<p>When the Jomsvikings commanded Thors back into war under threat to his village, Thors departed with a single longship. Unknown to him, six-year-old Thorfinn had hidden inside an empty water barrel.</p><p>At the Faroe Islands strait, they were ambushed by Askeladd''s mercenary fleet. Thors leaped aboard the enemy vessels completely unarmed. Defeating dozen hardened warriors with bare fists, he disarmed Askeladd in an honorable duel.</p><p>Yet Askeladd''s archers held Thorfinn hostage on the cliffside. Dropping his sword, Thors shielded his son with his own body, pierced by a barrage of black arrows. In his final breath, Thors whispered to Thorfinn: "A true warrior has no enemies. No one has the right to hurt anyone else."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (80, 19, 3.0, 'Askeladd''s Troop', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Ten years passed. Thorfinn was no longer the innocent child of Iceland. Armed with his father''s dual daggers, he was the deadliest scout in Askeladd''s warband, completing suicidal assassination missions in exchange for single combat duels against his father''s killer.</p><p>On the muddy shores of East Anglia, English soldiers fortified a stone castle over the river. While the Viking longships took heavy catapult fire, Thorfinn sprinted up the scaling ropes like a feral wolf, taking the garrison commander''s head within moments.</p><p>Throwing the bloody head at Askeladd''s boots, Thorfinn bared his teeth: "Our duel, Askeladd. Fight me now!" Askeladd chuckled cynically, unsheathing his broadsword: "You''re still just a brat blinded by rage, Thorfinn."</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (20, 'Oshi no Ko', 'Aka Akasaka, Mengo Yokoyari', '/uploads/cover_oshi_no_ko.jpg', 'MANGA', 'Drama, Mystery, Supernatural', 4.8, 'COMPLETED', 1, 2023, 'Japan', 'Manga', 'Showbiz, Idols, Reincarnation, Revenge, Mystery Drama', TRUE, FALSE, 'Country obstetrician Gorou Amamiya is murdered on the very night his idol patient Ai Hoshino delivers twin babies. He awakens reincarnated as her baby son, Aquamarine Hoshino, blessed with angelic looks and previous life memories. When tragedy strikes the idol world, Aqua plunges into the dark abyss of Japanese entertainment to execute revenge.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (81, 20, 1.0, 'Mother and Children', 0, TRUE, CURRENT_TIMESTAMP(), '<p>In a remote maternity hospital in Miyazaki Prefecture, gynecologist Gorou Amamiya lived a peaceful life, quietly obsessing over sixteen-year-old rising idol Ai Hoshino of B-Komachi.</p><p>His world turned upside down when Ai walked into his consultation room, sixteen weeks pregnant with twins. Despite the immense career risk in the ruthless Japanese idol industry, Ai was determined to give birth in secret: "Lies are an idol''s greatest form of love! I want both a family and my stage!"</p><p>On the night of the delivery, Gorou spotted an obsessive stalker lingering near the hospital entrance. Chasing him into the foggy woods, Gorou was struck from behind and pushed over a cliff to his death. His last thought was a desperate prayer for Ai''s safety.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (82, 20, 2.0, 'The Ultimate Idol Ai Hoshino', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Gorou opened his eyes to the soft glow of an incubator. Looking down at his chubby baby hands, he realized with shock that he had reincarnated as Ai Hoshino''s newborn son, Aquamarine.</p><p>Beside him in the twin crib lay his sister, Ruby—who, unbeknownst to him, was the reincarnation of Sarina, a young patient who had died of cancer in his previous hospital.</p><p>Growing up under Ai''s chaotic, loving care, the twins watched their mother conquer the Tokyo Dome stage. Ai''s eyes, shimmering with twin star-shaped pupils, radiated a hypnotic charisma that captivated millions. For a few brief years, life was a blissful dream.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (83, 20, 3.0, 'The Two Reincarnations', 10, TRUE, CURRENT_TIMESTAMP(), '<p>On the morning of B-Komachi''s premier concert, a knock rattled the apartment door. When Ai opened it holding flowers, the same deranged stalker who had murdered Gorou stabbed her through the chest.</p><p>Aqua rushed forward, pressing his tiny hands against the bleeding wound as Ai collapsed into his arms. With her dying breath, Ai stroked her children''s hair, her star eyes weeping crystal tears: "Aqua... Ruby... I love you. Ah, finally, I was able to say it without lying."</p><p>From that horrific morning forward, the innocence in Aqua''s soul vanished. Discovering that only someone with inside access could have leaked their private address, Aqua vowed to track down their biological father through the entertainment underworld, even if he had to burn his own soul to do it.</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (21, 'Dungeon Meshi (Delicious in Dungeon)', 'Ryoko Kui', '/uploads/cover_dungeon_meshi.jpg', 'MANGA', 'Fantasy, Comedy, Adventure', 4.9, 'COMPLETED', 1, 2024, 'Japan', 'Manga', 'Dungeon Cooking, Monsters, Culinary Fantasy, Party Adventure', TRUE, FALSE, 'After his sister Falin is swallowed whole by a Red Dragon on the deep dungeon floor, knight Laios and his remaining party members must mount an immediate rescue without supplies or gold. Their ingenious solution? Eating the monsters they slay along the way, guided by eccentric dwarf chef Senshi.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (84, 21, 1.0, 'Hot Pot with Red Dragon Broth', 0, TRUE, CURRENT_TIMESTAMP(), '<p>On the bottom floor of the Golden Kingdom dungeon, the expedition ended in disaster. The colossal Red Dragon incinerated the party''s rations, and Falin cast an emergency escape spell just as the dragon''s jaws snapped shut around her.</p><p>Teleported to the surface cemetery, Laios, the half-foot lockpicker Chilchuck, and the elven mage Marcille found themselves broke, starved, and empty-handed. But a dragon''s digestion takes approximately thirty days.</p><p>"If we go back to town to work for supplies, Falin will be digested into dragon droppings," Laios declared with chilling enthusiasm. "So we dive immediately... and eat the monsters we kill!" Marcille shrieked in disgust, but with her stomach growling violently, she had no choice but to follow.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (85, 21, 2.0, 'Roast Basilisk', 0, TRUE, CURRENT_TIMESTAMP(), '<p>On the second floor''s subterranean forest, the party encountered Senshi—a dwarf with a magnificent bushy beard who had spent ten years living in the dungeon studying monster ecology and culinary balance.</p><p>Senshi reprimanded Laios for improperly slaying a giant basilisk. "Look at how you damaged the meat! You must drain the venom glands from the neck before the toxin ruins the thighs!"</p><p>Setting up a massive wok forged from an adamantine dragon shield, Senshi stuffed the basilisk meat with wild dungeon leeks, garlic, and dried mandrake roots. When the golden roasted poultry was served, Marcille took a reluctant bite—and her eyes widened in pure gastronomic ecstasy. "It''s... it''s as tender as supreme pheasant!"</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (86, 21, 3.0, 'Senshi, The Dwarf Cook', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Advancing into the grand castle corridor, the party was ambushed by animated suits of living armor. Normal weapons bounced off the enchanted steel plates without leaving a scratch.</p><p>While Chilchuck and Marcille dodged halberd strikes, Laios observed the joints with fascinated glee. "Look closely! The metal isn''t possessed by ghosts! There are mollusks living inside the plate seams!"</p><p>Disarming the suits, Senshi cracked open the breastplate like a giant crab shell, extracting plump, steaming shellfish meat. Steamed over white wine and wild dungeon butter, the party enjoyed a five-star seafood feast in the middle of a monster-infested ruin.</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (22, 'The Greatest Estate Developer', 'Kim Hyunsoo, Lee Hyunmin', '/uploads/cover_estate_developer.jpg', 'MANHWA', 'Comedy, Fantasy, Slice of Life', 4.9, 'ONGOING', 1, 2023, 'Korea', 'Webtoon', 'Civil Engineering, Ondol, Hilarious Faces, Kingdom Building, Overpowered', TRUE, FALSE, 'Civil engineering student Suho Kim wakes up in the body of Lloyd Frontera—a lazy, drunken noble son whose family estate is drowning in bankruptcy. Armed with modern geotechnical calculations and a hilarious array of demonic business faces, Lloyd mobilizes shovel knights and summonable beasts to construct the greatest real estate empire in the kingdom.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (87, 22, 1.0, 'Civil Engineer in a Baron''s Body', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Suho Kim had studied four exhausting years of civil engineering in Seoul, surviving on convenience store cup noodles and calculus problem sets. When he fell asleep studying for his professional engineer license, he woke up in a four-poster bed inside a crumbling stone castle.</p><p>He was Lloyd Frontera: the eldest son of Baron Frontera, infamous for gambling debts, binge drinking, and throwing tantrums.</p><p>A loan shark knocked down the door demanding three thousand gold coins under penalty of selling the entire estate into slavery. Inspecting the drafty castle, the cracked foundation pillars, and the freezing stone floors, Suho''s engineer instincts flared: "Bankruptcy? Over my dead body! Bring me a shovel and surveying ropes!"</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (88, 22, 2.0, 'Floor Heating Saves the Kingdom', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Winter in the Frontera barony was brutal. The Baron and Baroness shivered beside smoke-filled fireplaces that wasted eighty percent of their thermal heat through chimney draft.</p><p>Lloyd mobilized the castle guards, excavating the living room subfloor to install traditional Korean ondol radiant heating flues. Using clay bricks, flat granite heat stones, and an exterior wood furnace, warm air circulated beneath the entire floorboards.</p><p>When the Baron returned from a freezing patrol and collapsed onto the cozy, radiant heated floor, tears streamed down his face: "Lloyd... my son... this floor is a gift from heaven!" Even rival lords visiting to collect debts refused to stand up, curling like sleepy kittens on the warm tiles.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (89, 22, 3.0, 'The Demonic Lloyd Face', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Constructing a massive aqueduct to irrigate the drought-stricken farmlands required digging through solid granite cliffs. Normal labor would take five years.</p><p>Summoning magical beast hamsters called Podong, Lloyd equipped them with tiny shovels and helmets. When greedy corrupt merchants attempted to bribe the workers and halt construction, Lloyd turned to face them.</p><p>His face twisted into an expression so grotesque, greedy, and demonic that the loan sharks dropped to their knees in terror. "You want to delay my project&mdash; Lloyd grinned, dark flames radiating from his smile. "If you don''t sign this contract at fifty percent discount, you''ll be digging ditches alongside the hamsters until retirement!"</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (23, 'Nano Machine', 'Hanjung Wolya', '/uploads/cover_nano_machine.jpg', 'NOVEL', 'Martial Arts, Action, Sci-Fi', 4.8, 'ONGOING', 1, 2022, 'Korea', 'Web Novel', 'Murim, Nano Machines, Demonic Cult, Martial Arts, System Growth', TRUE, FALSE, 'Cheon Yeo-Woon, an illegitimate son of the Demonic Cult leader, is constantly targeted for assassination by the six high clans. Near death in a poison ambush, a mysterious descendant from the 24th century arrives and injects high-tech nanomachine modules directly into his bloodstream.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (90, 23, 1.0, 'The Illegitimate Son of the Demonic Cult', 0, TRUE, CURRENT_TIMESTAMP(), '<p>In the bamboo grove outside the Demonic Cult''s grand shrine, fifteen-year-old Cheon Yeo-Woon coughed mouthfuls of black blood. The Poison Clan''s lethal Thousand-Gu neurotoxin had paralyzed his limbs.</p><p>Born to a peasant maid who caught the Lord''s eye, Yeo-Woon was despised by the six official clan wives. Before his mother died of poison, she made him swear never to learn martial arts to avoid execution.</p><p>As three masked assassins drew their curved sabers to finish him off, the sky distorted with blue electricity. A young man wearing a futuristic nano-suit materialized from a spatial rift. With two sonic energy blasts, the assassins disintegrated into ash. Kneeling beside Yeo-Woon, the descendant loaded an injector: "Ancestor, you must survive to preserve our bloodline."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (91, 23, 2.0, 'Injection from the 24th Century', 0, TRUE, CURRENT_TIMESTAMP(), '<p>A high-velocity pneumatic hiss echoed through the bamboo grove as billions of seventh-generation nanomachines entered Yeo-Woon''s bloodstream through his carotid artery.</p><p><b>[Nano Machine 7th Generation Online.]</b><br><b>[Analyzing biological host... Lethal neurotoxin detected. Initiating molecular breakdown and antitoxin synthesis.]</b></p><p>The burning agony in his chest subsided within seconds. A serene, synthetic female voice resonated directly within his consciousness. His optic nerves adjusted, displaying a three-dimensional holographic diagnostic of his meridians and blood vessels. For the first time in his life, Yeo-Woon possessed the weapon to fight back against the monsters of the cult.</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (92, 23, 3.0, 'Nano-Machine Healing and Scan', 10, TRUE, CURRENT_TIMESTAMP(), '<p>The Demonic Academy entrance examination gathered hundreds of ruthless clan scions in the martial hall. Cadets were required to spar against seasoned instructors to measure their internal energy.</p><p>When a senior disciple from the Poison Clan lunged with lethal tiger-claw strikes, the Nano system kicked in. <b>[Movement trajectory scanned. Simulating 142 counterattack vectors in augmented reality.]</b></p><p>To the audience, Yeo-Woon had never practiced martial arts. Yet he sidestepped the claw with microscopic precision, his palm strike landing directly on the disciple''s sternum with pinpoint internal force. The grand elder leaned forward from the balcony, his eyes flaring: "Who said that peasant boy had no talent&mdash;</p>');
MERGE INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION) KEY(ID) VALUES (24, 'Bocchi the Rock!', 'Aki Hamaji', '/uploads/cover_bocchi_the_rock.jpg', 'MANGA', 'Comedy, Slice of Life, Music', 4.8, 'ONGOING', 1, 2022, 'Japan', 'Manga', 'Kessoku Band, Guitarhero, Social Anxiety, Shimokitazawa, Rock Music', TRUE, FALSE, 'Hitori ''Bocchi'' Gotoh is an extremely introverted high school girl who practiced guitar for six hours every single day in her closet, gaining viral fame online as ''guitarhero''. When spunky drummer Nijika Ijichi literally drags her into a live house park, Bocchi unexpectedly becomes the lead guitarist of Kessoku Band.');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (93, 24, 1.0, 'Lonely Rolling Guitarhero', 0, TRUE, CURRENT_TIMESTAMP(), '<p>For three straight years of middle school, Hitori Gotoh spent every day inside her bedroom closet, practicing her father''s vintage Gibson Les Paul Custom for six hours a day until her fingertips bled.</p><p>Under the anonymous handle ''guitarhero'', she posted blazing rock covers that accumulated over thirty thousand subscribers. Yet in real life, she couldn''t make eye contact with a cashier without having an existential panic attack.</p><p>Desperate to make friends in high school, she sat inside the playground slide with her guitar case, hoping someone would notice. Suddenly, a hyperactive blonde girl with a dorito-shaped hair ahoge grabbed her sleeve: "Hey! You play guitar, right? Our lead guitarist just bailed before tonight''s gig! Help us out!"</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (94, 24, 2.0, 'The Starry Live House Encounter', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Bocchi was dragged into the dimly lit basement of Live House STARRY in Shimokitazawa. The aroma of guitar amp tubes and stage haze made her knees tremble.</p><p>Nijika Ijichi introduced her to Ryo Yamada—a cool, aloof bassist with blue hair who spent all her money on vintage instruments and survived by eating weeds in the park.</p><p>When the first rehearsal began, Bocchi''s social anxiety was so paralyzing that she curled inside a cardboard mango storage box to play. Yet even from inside the box, the precision of her rhythm chords made Ryo stop in astonishment: "Nijika... where did you find this bizarre girl? She''s incredible."</p>');
MERGE INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT) KEY(ID) VALUES (95, 24, 3.0, 'Kessoku Band Assembled', 10, TRUE, CURRENT_TIMESTAMP(), '<p>Joined by energetic rhythm guitarist and vocalist Ikuyo Kita—the outgoing girl whose radiant aura was so blinding Bocchi literally melted into dust—Kessoku Band was finally complete.</p><p>For their audition before live house manager Seika Ijichi, the tension was suffocating. If they failed, they would never be allowed to perform on the STARRY stage.</p><p>As Kita started the opening chords, Bocchi remembered her lonely days in the dark closet. Clicking her overdrive pedal, she kicked open the imaginary box, letting loose a blistering, emotional pentatonic guitar solo that resonated through the concrete basement. Seika crossed her arms, a small smile breaking across her stern face: "You pass. Don''t embarrass my stage."</p>');
ALTER TABLE NOVELS ALTER COLUMN ID RESTART WITH 100;
ALTER TABLE CHAPTERS ALTER COLUMN ID RESTART WITH 300;
UPDATE SYSTEM_SETTINGS SET SETTING_VALUE = '1' WHERE SETTING_KEY = 'featured_novel_id';
UPDATE SYSTEM_SETTINGS SET SETTING_VALUE = 'false' WHERE SETTING_KEY = 'secured_mode';
SET REFERENTIAL_INTEGRITY TRUE;
